const html: string = "<div>\n        <p>\n          <span>1. Fundamentals&#160;</span>\n        </p>\n        <p>\n          <span>1.1. Gamblinglar faqat 21 yoshdan oshgan shaxslardan qabul qilinadi.\n            Mijoz yurisdiktsiyasining qonun hujjatlarida yuqoriroq belgilab qo'yilgan bo'lsa\n            Qimor o'yinlarida qatnashish uchun minimal yosh quyidagilar:\n            yoshi kattaroq. Yoshroq shaxs tomonidan ro'yxatdan o'tish, depozit yoki pul tikish\n            21 yosh (yoki yurisdiktsiyada qonun talab qiladigan yoshga to'lmagan).\n            Mijoz) Qoidalarning qo'pol buzilishi: Kompaniya yopish huquqiga ega\n            hisob, tikish bekor va qaytarib holda pul ushlab qolish.&#160;</span>\n        </p>\n        <p>\n          <span>\n            1.2. Gamblinglar faqat qoidalarga rozi bo'lgan shaxslardan qabul qilinadi,\n            yanada bukmekerlik kompaniyasi tomonidan tashkil etilgan (Imba.bet). Har qanday stavka\n            mijozning ushbu qoidalarni bilishini tasdiqlaydi va\n            Men ular bilan roziman. Ma'muriyat bekor qilish huquqiga ega\n            ushbu Qoidalarni buzgan holda tikilgan garovlar. Ma'muriyat unday emas\n            aniq qachon bo'lishi uchun javobgarlikni o'z zimmasiga olmaydi\n            tikilganligi ma'lum bo'ldi yoki keyinchalik aniqlandi\n            Qoidalarni buzgan holda amalga oshirilgan.\n          </span>\n        </p>\n        <p>\n          <span>\n            1.3. Ma'muriyat qabul qilmagan shaxslardan garovlarni qabul qilmaslik huquqiga ega\n            ushbu qoidalarga rioya qilish.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            1.4. Qabul qilish bilan bog'liq firibgarlik faoliyati aniqlangan taqdirda\n            stavkalari yoki moliyaviy operatsiyalar, ma'muriyat to'xtatish huquqiga ega\n            tikish bekor tomonidan bunday harakatlar, yopish\n            mablag'lar qoldig'i qaytarilmasdan hisoblar va murojaat qilish\n            firibgarlik sodir etganligi bo'yicha huquqni muhofaza qilish organlari\n            harakatlar.\n          </span>\n        </p>\n        <p>\n          <span>\n            1.5. Oldinda (goldan keyin) garovlar aniqlansa, hisob\n            qaytarilmasdan bloklangan.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            1.6. Mijozdan ishonchli garovlar bo'yicha garovlar bo'lsa - hisob\n            qaytarilmasdan bloklangan.\n          </span>\n        </p>\n        <p>\n          <span>\n            1.7. Bahsli masalalar bo'yicha da'volar 10 kun ichida qabul qilinadi\n            yozma ariza asosida tadbir tugaganidan keyin.\n            Barcha bahsli vaziyatlar bo'yicha yakuniy qaror tomonidan qabul qilinadi\n            boshqaruv.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            1.8. Ushbu qoidalar va ularga kiritilgan tuzatishlar sanadan boshlab kuchga kiradi\n            saytdagi nashrlar va barcha tikish va harakatlar uchun amal qiladi,\n            e'lon qilingan kundan boshlab, ular bilishidan qat'i nazar, tuzilgan\n            qoidalarning ushbu versiyasi kuchga kirishi yoki yo'qligi haqida mijozlar. Hammasi\n            oldingi qoidalar endi haqiqiy emas deb hisoblanadi.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            1.9.Kompaniya o'yin hisobini yopish huquqini o'zida saqlab qoladi,\n            Agar kompaniya tikish va balansni bekor qilish\n            Quyidagilar aniqlandi: a) garov tikish vaqtida garov egasi\n            voqea natijasi to'g'risidagi ma'lumotlar (belgilangan o'yin); b) Gambling\n            o'yinning bevosita ishtirokchisi (sportchilar, hakamlar,\n            murabbiylar va boshqalar) yoki u bilan kelishilgan holda ish yurituvchi shaxs; c) tikish\n            kontsertda harakat qilayotgan bir guruh Bettors tomonidan yakunlandi\n            (sindikat) Jamiyat tomonidan belgilangan chegaralardan oshib ketish uchun;\n            d) bitta Bettorda bir nechta o'yin hisoblari mavjud; e) ishtirokchi\n            tikish maxsus dasturiy ta'minotdan foydalanganlikda gumon qilinmoqda\n            avtomatlashtirish imkonini beruvchi dasturiy ta'minot yoki texnik vositalar\n            tikish jarayoni; f) har qanday vijdonsiz\n            ma'lumot olish yo'llari yoki belgilangan cheklovlarni chetlab o'tish\n            kompaniya tomonidan; g) o'yin hisobiga ishonish uchun asoslar mavjud\n            tikish yoki boshqa tegishli faoliyat uchun foydalanilmaydi\n            o'yinlar bilan. Yuqorida tavsiflangan vaziyatlarda Bettor hisobidagi qoldiq\n            qayta hisoblab chiqiladi va alohida ko'rib chiqiladi.\n          </span>\n        </p>\n        <p>\n          <span>2. Omonatingizni to'ldirish va yutuqni olish</span>\n        </p>\n        <p>\n          <span>\n            2.1. Tikishlar chiziq asosida qabul qilinadi - bo'lajak voqealar ro'yxati\n            bukmeker tomonidan taklif qilingan kotirovkalar bilan - koeffitsientlar\n            g'alaba qozonish. Kotirovkalar har qanday tikishdan keyin o'zgarishi mumkin, ammo shartlar\n            ilgari qo'yilgan tikishlar bir xil bo'lib qoladi. O'yinchilarga pul tikishdan oldin\n            qatordagi barcha o'zgarishlarni aniqlash kerak.\n          </span>\n        </p>\n        <p>\n          <span>\n            2.2. Joylashtirilgan tikish, ularni serverga joylashtirish va ularni qabul qilishdan keyin\n            so'rov bo'yicha o'yinchidan tikish va kupon raqamini qabul qilish haqida xabar\n            o'yinchilar bekor qilinishi yoki tuzatilishi mumkin emas, ammo 4.5-bandga muvofiq\n            ushbu Qoidalar ma'muriyati tomonidan bekor qilinishi mumkin. Tanaffus\n            ulanishlar yoki boshqa aloqa uzilishlari asos bo'lmaydi\n            agar garov serverda ro'yxatdan o'tgan bo'lsa, garovni bekor qilish. Tariflar\n            faqat joriy hisob balansidan oshmaydigan miqdorda qabul qilinadi\n            mijoz. Tikishni ro'yxatdan o'tkazgandan so'ng, garov summasi hisobdan yechib olinadi\n            hisoblar. Tikishlar hisoblangandan so'ng, yutuq summasi mijozning hisobiga o'tkaziladi\n            .\n          </span>\n        </p>\n        <p>\n          <span>\n            2.3. Quyidagi garov turlari ajratiladi: “yakka”,\n            &quot;ekspress&quot; va \"tizim\". Yagona garov -\n            Faqat bitta voqea natijasini bashorat qilishingiz kerak bo'lgan garov.\n            Yagona garovlar har qanday voqea uchun qabul qilinadi. Yakkalik bahslarida g'alaba qozonish\n            garovlar garov summasining yutuq koeffitsientiga ko'paytirilganiga teng.\n            Ekspress - ko'proq natijani taxmin qilish kerak bo'lgan garov\n            bir vaqtning o'zida bitta hodisa. Agar kamida bitta voqea bo'lsa\n            ekspress garov noto'g'ri taxmin qilingan bo'lsa, butun ekspress garov yo'qolgan hisoblanadi. B\n            ekspress har qanday sportning istalgan kombinatsiyasini o'z ichiga olishi mumkin.\n            Ekspressga bog'liq hodisalarni qo'sha olmaysiz: xuddi shu hodisa\n            ekspressda bir necha marta ishtirok eta olmaydi, bog'lanmaydi\n            ekspress garovda o'yin natijasi va unda ishtirok etuvchi jamoaga tikilgan garov\n            o'yin (masalan: keyingi bosqichga o'tish va hokazo). Ekspressda bo'lsa\n            bog'liq hodisalar bo'lib chiqdi, keyin faqat hisoblash uchun\n            ulardan biri eng yuqori koeffitsientga ega. G'alaba darajasi\n            ekspress garov barchaning yutuq koeffitsientlarini ko'paytirish yo'li bilan hisoblanadi\n            ekspressga kiritilgan voqealar. Tezyurar poyezdlardagi yutuq summaga teng\n            tikish ekspress garovining yutuq koeffitsientiga ko'paytiriladi. Koeffitsient\n            yutuq cheksiz. Tizim - ekspress poezdlarning to'liq kombinatsiyasi\n            oldindan belgilangan hodisalar sonidan ma'lum hajmdagi\n            (tizimdagi maksimal hodisalar soni 16 ta). Har bir kombinatsiya\n            tizimda alohida ekspress sifatida hisoblanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            2.4. Minimal stavka ma'muriyat tomonidan belgilanadi. Maksimal\n            liniyada bitta tikish uchun to'lov 3 million rubl, jonli - 1 million\n            rubl Boshqa valyutalardagi pul tikish uchun maksimal to'lov belgilanadi\n            ofis kursi bo'yicha qayta hisoblangan. Ba'zi toifadagi o'yinlar va tikish uchun\n            maksimal yutuq uchun maxsus limitlar belgilanishi mumkin,\n            ushbu Qoidalarning tegishli bo'limlarida ko'rsatilgan.\n          </span>\n        </p>\n        <p>\n          <span>\n            2.5. Ma'muriyat boshiga maksimal stavkani cheklash huquqiga ega\n            individual hodisalar, shuningdek, maksimalni cheklash yoki oshirish\n            sabablarini bildirmasdan yoki tushuntirmasdan ma'lum bir mijozga tarif.\n            Ma'muriyat aniq cheklash yoki rad etish huquqiga ega\n            mijozlar taqdim etilayotgan xizmatlarga yoki ularsiz xizmatlarga kirishda\n            bildirishnomalar va sabablarni tushuntirish.\n          </span>\n        </p>\n        <p>\n          <span>\n            2.6. Gamblinglar tadbir boshlanishidan oldin qabul qilinadi. Bunga ko'ra\n            negadir taklif haqiqiy boshlanganidan keyin joylashtirildi\n            hodisalar, bunday garov bekor hisoblanadi. Istisno\n            \"Jonli\" voqealarga tikish, ya'ni garov tikish\n            o'yinning borishi. Bunday garovlar amalga oshirilgan taqdirda haqiqiy hisoblanadi\n            o'yin tugashidan oldin.\n          </span>\n        </p>\n        <p>\n          <span>\n            2.7. Ma'muriyat bekor qilish huquqini o'zida saqlab qoladi\n            “Jonli” garov, agar ma’muriyat mijozdan shubhalansa\n            tikish vaqtida ko'rsatilgan voqea natijasi haqida ma'lumot bor edi\n            darajasi. Bunday holda, Ma'muriyat sababni isbotlashga majbur emas\n            bunday shubhalar paydo bo'ladi&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            2.8. Agar mijoz “Jonli” pul tikish jarayonida\n            koeffitsientlar yoki garov parametrlarining o'zgarishi bilan kelishilgan (handikap,\n            jami va h.k.), u holda garov voqea hisobi bo'lsa ham qabul qilinadi\n            tikish ro'yxatdan o'tgan vaqtga qadar o'zgartirildi.\n          </span>\n        </p>\n        <p>\n          <span>3.&#160; garovini hisoblash xususiyatlari</span>\n        </p>\n        <p>\n          <span>\n            3.1. Satrda ko'rsatilgan hodisaning boshlanish sanasi va vaqti\n            informatsion xususiyatga ega. Noto'g'ri belgilangan sana, vaqt yoki\n            qo'shimcha ma'lumotlar (turnirning holati yoki bosqichi, birinchisining balli).\n            o'yin va boshqalar) garovni bekor qilish uchun asos emas. Holatda\n            agar voqea dastlab e'lon qilinganidan oldin yoki kechroq sodir bo'lgan bo'lsa\n            sana, natija haqiqiy hisoblanadi va garovlar hisobga olinadi\n            tadbir boshlanishidan oldin amalga oshirilgan bo'lsa, amal qiladi. Holatda\n            3 yoki undan ortiq kun tikish uchun boshlanmagan voqeani keyinga qoldirish\n            qaytmoqdalar. Agar boshlanmagan voqea kamroq muddatga qoldirilsa\n            3 kun davomida tariflar o'z kuchini saqlab qoladi, ammo ma'muriyat qabul qilish huquqiga ega\n            voqea tugashini kutmasdan tikishlarni qaytarish to'g'risida qaror, qaysi haqida\n            O'yinchilarga rasmiy natijalar ma'lum qilinadi. Agar NBA, NHL mos keladi\n            MLB yoki NFL o'tkazilmadi yoki belgilangan kunda tugallanmagan\n            garovlar ertasi kuni darhol qaytariladi, bundan mustasno\n            voqea sanasi noto'g'ri ko'rsatilgan holatlar.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.2. Hodisalar ro'yxatida birinchi o'rinni maydondagi jamoa ko'rsatadi\n            qaysi o'yin o'tkazilmoqda. Agar o'yin jamoa maydonida o'tkazilsa,\n            voqealar ro'yxatida ikkinchi o'rinda ko'rsatilgan (jamoalarning o'yinlari bundan mustasno\n            bitta shahar yoki viloyat), ushbu o'yinga tikilgan tikish qaytariladi va dan\n            tezyurar poyezdlar bundan mustasno. Neytral maydonda o'yin o'tkazish emas\n            garovlarni bekor qilish uchun asos hisoblanadi. Agar sarlavhada ko'rsatilgan bo'lsa\n            musobaqalar o'tkaziladigan joyga mos ravishda, yozib olishga ruxsat beriladi\n            sportchi yoki uy jamoasi birinchi emas. Bu holda, tikish emas\n            qaytarilishi mumkin. &#160;\n          </span>\n        </p>\n        <p>\n          <span>3.3. To'xtatilgan voqealar: </span>\n        </p>\n        <p>\n          <span>\n            3.3.1. Voqea sodir bo'lgan hisoblanadi, agar u uzilib qolsa va\n            qoidalar bilan tartibga solingan o'yinning kamida ma'lum bir qismini o'ynagan\n            to'liq vaqt. Umuman o'yinga pul tikish uchun bu: futbol - 65 min.\n            (agar o'yin formati standart bo'lmasa, o'yinning 70 foizi\n            vaqt); basketbol - 35 min. (NBA va boshqa turnirlar uchun\n            48 daqiqalik o'yinlar) va 28 daqiqa. 40 daqiqalik o'yinlar bo'lgan turnirlar uchun;\n            xokkey - 45 daqiqa; Bandy - 60 daqiqa; Amerika futboli - 50\n            min; beysbol - 5 inning; boshqa sport turlari - kamida 70%\n            o'yin vaqti. Ballar teng bo'lgan holatlar bundan mustasno\n            qoidalar ruxsat bermaydigan sport turlari bo'yicha o'yinlarni to'xtatish vaqti\n            durang (basketbol, beysbol, amerika futboli va boshqalar). Bularda\n            Bunday hollarda voqea sodir bo'lmagan deb hisoblanadi. Agar voqea tan olinsa\n            muvaffaqiyatsiz bo'lsa, \"Pass\" ga tikilgan garovlar qaytariladi. Agar voqea\n            haqiqiy deb tan olingan bo'lsa, \"Pass\" ga garovlar ga muvofiq hisoblanadi\n            o'yin to'xtatilgan paytdagi haqiqiy hisob va durang bo'lsa\n            fakturalar - to'lovni qaytarish. Eng yirik homiyligida o'tkaziladigan tadbirlar uchun\n            xalqaro tashkilotlar (masalan, futbolda FIFA va UEFA), qachon\n            Hodisa vaqti haqidagi ma'lumotlar tezda jamoat mulkida paydo bo'ladi.\n            o'yinning tugashi (30 soatgacha), ma'muriyat qarori bilan barcha garovlar mumkin\n            yakuniy natijaga qarab hisoblab chiqiladi. ga tikish uchun\n            o'yinning alohida qismlari (basketbolda chorak, futbolda yarim),\n            xokkey va shunga o'xshash davrlar) agar ular to'xtatilgan bo'lsa,\n            keyin kamida 70% o'tgan bo'lsa, ular o'ynalgan deb hisoblanadi\n            o'yin vaqti ushbu qism uchun qoidalar bilan tartibga solinadi\n            mos. O'tgan o'yin vaqtini hisoblash faqat hisobga olinadi\n            butun daqiqalar o'ynadi va kasrlarni yaxlitlash.\n            Misol uchun, xokkey o'yini ba'zilarining 14-daqiqasida to'xtatildi\n            13 daqiqa 20 soniya davom etgan. Bu holda\n            13 to'liq daqiqa o'ynaldi, bu 65%, ya'ni kamroq,\n            70% dan ortiq. Shu sababli, ushbu davr uchun garovlar bekor qilinadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.3.2. Ta'rifga kirmaydigan uzilgan hodisa\n            sodir bo'lgan voqea, agar u haqiqiy emas deb topilishi mumkin\n            3 soat ichida o'ynash tugamagan.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.3.3. Bo'lib o'tmagan deb topilgan to'xtatilgan voqealar uchun qayting\n            Barcha garovlar garovlarga bo'ysunadi, garovlar bundan mustasno, natijasi vaqtga kelib\n            Hodisani to'xtatish o'ziga xos tarzda aniqlanadi (masalan, 1-o'rinni kim oladi\n            maqsad, kartani oladi, jami \"tutgan\" bor edi va hokazo). uchun\n            to'xtatilgan voqealar garovlar so'zsiz qaytarilishi shart\n            yarmlarning qiyosiy ko'rsatkichlari (davrlar va boshqalar).\n          </span>\n        </p>\n        <p>\n          <span>\n            3.3.4 Bo'lib o'tgan deb e'tirof etilgan to'xtatilgan hodisalar hisoblab chiqiladi\n            umumiy asosda. To'xtatilgan o'yinga (o'yin, musobaqa yoki\n            ortga hisoblash boshlanmagan (masalan, 76 dan 90 gacha gol).\n            min, agar o'yin 70-daqiqada to'xtatilsa) qaytarib beriladi. Gambling\n            boshlangan, ammo tugallanmagan voqealar (masalan, maqsad bo'ladimi?\n            Agar o'yin 70-daqiqada to'xtatilsa, 61 daqiqadan 75 daqiqagacha bo'lgan interval)\n            haqiqiy deb hisoblanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.3.5 Ba'zi sport turlari uchun qo'shimcha funktsiyalar mavjud\n            stavkalarni hisoblash, agar ular qoidalarning tegishli bandlarida ko'rsatilgan bo'lsa.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.4. Agar tugallangan hodisaning dastlabki natijasi keyinroq bo'lsa\n            biron-bir sababga ko'ra bekor qilingan, bekor qilish hisobga olinmaydi va\n            stavkalar asl (haqiqiy)ga muvofiq to'lanadi.\n            natija. Natija e'lon qilingan\n            rasmiy bayonnomalar va boshqa rasmiy manbalar asosida\n            tadbir tugagandan so'ng darhol ma'lumot. Holatda\n            rasmiy manbalarda natijalar yo'qligi, ma'muriyat huquqiga ega\n            muqobil axborot manbalaridan foydalanish, shu jumladan\n            o'yindagi o'z vakilingizdan ma'lumot. Agar qatorda bo'lsa\n            Tanlovning nomi manbani aniq ko'rsatadi (masalan,\n            televizion eshittirish), keyin belgilashda u ustuvorlikka ega\n            natija. Agar voqea to'xtatilsa va ertasi kuni bilan o'ynasa\n            boshidanoq, keyin hisob-kitob qilish uchun birinchi o'yin uzilgan hisoblanadi\n            hodisa va 3.3-bandga muvofiq hisoblanadi\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5. Ma'muriyat garovni haqiqiy emas deb topishga haqli\n            hollarda:\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5.1 Tikishni qabul qilishda xodimlarning xatolari yoki dasturiy ta'minotdagi nosozliklar\n            (koeffitsientlardagi aniq xatolar, koeffitsientlarning nomuvofiqligi\n            turli lavozimlar va boshqalar)\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5.2 Agar sportchiga xos bo'lmagan janglarning aniq belgilari bo'lsa. Holatda\n            Fonbetdagi o'yinlarning sportga xos bo'lmagan tabiati haqida shubhalar paydo bo'ladi\n            yoki xalqaro tashkilotlardan EWS-FIFA ogohlantirishi bilan,\n            Federbet va Tennis Integrity Unit, ma'muriyati huquqiga ega\n            avval shubhali garov o'tkazgan Mijozning garovlarini bloklash\n            xalqaro tashkilotning xulosasi va garovlarni tan olish\n            sportga xos bo'lmagan xatti-harakatlar fakti aniqlansa, haqiqiy emas\n            kurash. Ma'muriyat futbolchilarga dalil taqdim etishga majbur emas\n            va xulosalar.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5.3 Tikishni qabul qilish bilan bog'liq firibgarlik harakatlarini aniqlash\n            yoki operatsiyalar, soxta hujjatlarni taqdim etish;\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5.4 Boshqa birovning hisobidan o'ynash faktini yoki sodir bo'lganligini tasdiqlash\n            shaxsiy hisobingizdan ruxsatsiz shaxslar tomonidan foydalanishga shubha.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.5.5 Tekshiruv protsedurasidan o'tishni rad etish, shuningdek, sodir bo'lgan taqdirda\n            qayta ro'yxatdan o'tkazish faktini tasdiqlash (shu jumladan foydalanish\n            boshqa shaxslarning shaxsiy ma'lumotlari, hujjatlari, shu jumladan. bekor va\n            soxta).\n          </span>\n        </p>\n        <p>\n          <span>3.5.6 Ushbu qoidalarni buzgan boshqa hollarda.</span>\n        </p>\n        <p>\n          <span>\n            3.6. Agar garov haqiqiy emas deb topilsa,\n            ushbu garovni qaytarish va agar u ekspress yoki tizimga kiritilgan bo'lsa, u holda\n            hisoblash uchun 1 koeffitsient bilan hisobga olinadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.7. Barcha joriy natijalar, o'yin vaqti, boshqa qo'shimchalar\n            saytda ko'rsatilgan ma'lumotlar faqat sifatida xizmat qiladi\n            ma'lumotnoma ma'lumotlari. Ma'muriyat bu ma'lumotni ta'minlashga intiladi\n            to'g'ri edi, lekin tikish oqibatlari uchun javobgar emas,\n            ushbu ma'lumotlar asosida tuzilgan. Mijozga maslahat beriladi\n            tikish hisob-kitoblarining to'g'riligini tekshirish, shu jumladan jonli garovlar,\n            rasmiy ma'lumot manbalaridan foydalaning (rasmiy veb-saytlar\n            sport tadbirlari tashkilotchilari).\n          </span>\n        </p>\n        <p>\n          <span>\n            3.8. Sizni chetlab o'tishga imkon beruvchi bir vaqtning o'zida tikish va tikish\n            mavjud maksimal tikish yoki bir xil uchun to'lov miqdori\n            bir guruh shaxslardan (o'yinchilarning sindikati va boshqalar) bir xil natijaga yo'l qo'yilmaydi. Yo'q\n            Xuddi shu kombinatsiyaga takroriy tikish qo'yishga ruxsat beriladi\n            Agar umumiy potentsial to'lov oshib ketgan bo'lsa, natijalar\n            maksimal. Ma'muriyat bunday tariflarni e'lon qilish huquqiga ega\n            yaroqsiz.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.9. Hisob yoki boshqa o'yin parametrlaridagi har qanday o'zgarishlar\n            rasmiy hakamning qarori (masalan, ofsayd tufayli o'tkazib yuborilgan gol,\n            video ko'rish, tennis nuqtasini bekor qilish yoki qayta ko'rib chiqishdan keyin,\n            voleybol va boshqalar) yoki ishtirokchilarning o'zaro kelishuvi (masalan,\n            chetlatilgandan keyin teng kuch bilan o'ynash va hokazo) sabab emas\n            tikishlarni bekor qilish.\n          </span>\n        </p>\n        <p>\n          <span>\n            3.10. Presedentsiz bahsli vaziyatlarda final\n            Qaror bukmeyker tomonidan qabul qilinadi (Imba.bet).\n          </span>\n        </p>\n        <p>\n          <span>4. &#160; tikishning asosiy turlari</span>\n        </p>\n        <p>\n          <span>\n            4.1. Haqiqiy natijaga tikish. Sizsiz o'yinlarga pul tikishingiz mumkin\n            nogironlikni hisobga olgan holda, agar tegishli koeffitsientlar ko'rsatilgan bo'lsa (birinchi\n            o'rinlar - birinchi jamoani yutganligi uchun (\"1\"), ikkinchisi uchun\n            pozitsiyasi - durang uchun \"X\" koeffitsienti, uchinchi o'rinda -\n            ikkinchi jamoani yutish koeffitsienti (\"2\"). Bunda\n            Bunday holda, garov natijasi o'yinning haqiqiy natijasi hisoblanadi. Shuningdek\n            1-jamoa mag'lub bo'lmasligiga tikishingiz mumkin\n            (&quot;1X&quot;), 2-jamoa yutqazmaydi (&quot;X2&quot;) yoki yo'q.\n            durang (&quot;12&quot;) bo'ladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.2. O'yindagi har bir jamoaning g'alabasiga garovlar, handikapni hisobga olgan holda\n            (andikap). Noqonuniylik bukmeker tomonidan belgilanadi va bo'lishi mumkin\n            ijobiy, salbiy yoki nolga teng. Aniqlash uchun\n            qaysi jamoa tomonidan kiritilgan haqiqiy gollarga tikilgan garov natijasi\n            tikish amalga oshiriladi, u olib qo'yiladi (agar nogironlik salbiy bo'lsa) yoki\n            tanlangan jamoa uchun nogironlik qo'shiladi (agar nogironlik ijobiy bo'lsa)\n            (ikkinchi jamoa uchun nogironlik hisobga olinmaydi). Agar keyin\n            Agar o'yin natijasi tanlangan jamoa foydasiga bo'lsa, unda\n            garov yutilgan deb hisoblanadi. Durang bo'lsa - tikish\n            qaytadi. Misol uchun, agar birinchi buyruq o'rnatilgan bo'lsa\n            salbiy handikap \"-1\" va o'yin yakunlandi: a) hisob bilan\n            0:0, yutqazilgan garov; b) 1:0 hisobi bilan garov qaytariladi; c) bilan\n            hisob 2:0, garov yutibdi. A agar ijobiy nogironlik belgilansa\n            &quot;+0,5&quot; va o'yin yakunlandi a) 0:1 hisobida, tikish\n            yo'qolgan; b) 0:0 yoki 1:0 hisobi bilan garov yutib olinadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.3. Osiyo nogironligi. G'alabaga yoki to'plamga, shu jumladan, handikapga tikish\n            (handikap), 0,25 ga karrali (lekin 0,5 ga karrali emas). Bu garov\n            bilan yarmi miqdorida ikki tikish sifatida hisoblanadi\n            bir xil koeffitsientlar va &quot;oddiyning eng yaqin qiymatlari bilan\n            uchun\" va \"muntazam jami\" (butun yoki 0,5 ga karrali).\n            Satrdagi bunday hodisalar \"Osiyo\" prefiksi bilan belgilanadi. Holatda\n            Osiyo handikap tikish ekspress yoki tizimga kiritilgan, keyin\n            Ushbu garovni hisoblashda yutuq koeffitsientlaridan foydalaniladi, bu esa\n            agar u bir raqamli hisoblangan bo'lsa, olingan bo'lar edi. Agar ikkalasi ham g'alaba qozonsa\n            Yarim tikish uchun garov koeffitsienti (K) hisob-kitoblarda hisobga olinadi.\n            Agar yarim garov g'alaba qozonsa, ikkinchisi yutqazsa, hisob-kitob\n            (K+1)/2 koeffitsienti qabul qilinadi. Agar bitta yarmi tikilgan bo'lsa\n            yo'qolgan, ammo boshqa xarajatlarga ko'ra, tezkor poezdlarda koeffitsientlar hisoblanadi\n            0,5. Agar ikkala yarim garov yutqazilsa, butun garov hisobga olinadi\n            yo'qolgan.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.4. Gollarning umumiy soni, ochkolar, burchaklar, jarima zarbalari,\n            kartalar va idora tomonidan tashkil etilgan boshqa tadbirlar (&quot;Batafsil -\n            Kamroq.\" Yuqoridagi hodisalar soni quyidagicha aniqlanadi\n            umumiy qiymat \"jami\" deb ataladi va idora tomonidan belgilanadi. Holatda\n            jami bo'lsa, tikish qaytariladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.5. Musobaqada g'alaba qozonish yoki keyingi bosqichga o'tish uchun garovlar\n            turnirlar. Agar ishtirokchi biron bir sababga ko'ra tanlovda e'lon qilgan bo'lsa\n            chunki men musobaqani boshlay olmadim, bu ishtirokchiga tikish\n            qaytarilishi shart. Ikki yoki undan ortiq ishtirokchi baham ko'rsa\n            tanlovda g'alaba qozonish, ularning har biri uchun yutuq to'lanadi\n            formuladan foydalangan holda hisoblangan yutuq koeffitsienti asosida\n            K=(Kish-1)/N+1, bu yerda Kish – har bir ishtirokchi uchun dastlabki koeffitsient,\n            N - tanlov g'oliblari soni.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.6. Muayyan o'yin hisobi va o'yin vaqtiga tikish. Shakl darajasida\n            &quot;vaqt o'yini&quot; birinchisining natijasini bir vaqtning o'zida taxmin qilish kerak\n            yarmi va butun o'yin. Ushbu natijalarni ko'rsatish uchun qatorda\n            bosh harflar ishlatiladi: P - g'alaba, N - durang, 1-da\n            1-bo'limning natijasi o'z joyida, o'yin esa ikkinchi o'rinda. Natija 2\n            bu garovni hisoblash uchun tanaffusning ahamiyati EMAS. Misol uchun, o'yin bo'lsa\n            1:1 hisobi bilan yakunlandi, birinchi bo'lim esa 1:0, keyin esa g'alaba qozondi\n            P1N.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.7. Tur yoki o'yin kuni statistikasiga garovlar. In bo'lsa\n            tur haqiqiy emas deb topilgan (4.3-band mezonlariga ko'ra) yoki bekor qilingan (bo'yicha).\n            4.1-band mezonlari bo'yicha kamida bitta o'yin, keyin tur statistikasiga tikish\n            Natijasi aniq bo'lgan garovlar bundan mustasno, qaytarilishi kerak\n            aniqlangan (masalan, 0:0 durang bo'ladimi, barcha jamoalar gol kiritadimi va hokazo).\n            Bukmeker kontor garovlarni qaytarish to'g'risida qaror qabul qilish huquqiga ega\n            tur yoki o'yin kuni statistikasi, agar ishonchli bo'lsa\n            tur boshlanishidan oldin o'yinlardan biri bekor qilinganligi haqida ma'lumot, bu haqda o'yinchilar\n            Rasmiy natijalarda qayd etilgan. Ko'rsatkichlarni hisoblash uchun\n            tennis o'yinlari kuni o'yinni yakunlamagan o'yinchiga (by\n            har qanday sababga ko'ra), qolgan barcha to'plamlar va o'yinlarda hisobga olinadi\n            mag'lubiyat. Mezbonlar qatorda ko'rsatilgan jamoalar yoki o'yinchilardir\n            birinchi o'rinda.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.8. Gollar yoki ochkolarning juft yoki toq umumiy soniga tikish\n            mos. Koeffitsientlar qatorda ko'rsatilgan. Hisob 0:0 – teng.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.9. Shaxsiy ishlash yoki o'yinchilarni taqqoslashga garovlar\n            (ishtirokchilar). Agar o'yinchi maydonga kirmagan bo'lsa (ishtirok etmagan), keyin\n            Uning ishtirokidagi tadbirlarga garovlar qaytariladi. Ishtirokchilar uchun,\n            hodisani tugatmaganlar, ko'rsatkichlar bo'yicha hisoblanadi\n            olib tashlash (olib tashlash) vaqtidagi haqiqiy natija va maqsadlar uchun\n            hisob-kitoblarga ko'ra, bunday ishtirokchilar finalda oxirgi o'rinni egallaydilar\n            protokol. \"Het-trik bo'ladimi\" garovlari hisobga olinadi\n            agar o'yinchi uchta yoki undan ko'p gol urgan bo'lsa, g'alaba qozondi. Tariflar \"bo'ladi\n            dubl bormi? Agar o'yinchi ikki yoki undan ko'p ball to'plagan bo'lsa, g'olib deb hisoblanadi\n            maqsad. O'yinchining ishlashiga tikilgan garovlarda o'yinchining o'zi kiritgan gollari\n            uning ko'rsatkichlarida darvozalar hisobga olinmaydi. Bilan bog'liq stavkalarda\n            jamoaviy o'yin, jamoaning avtogolga kiritgan gollari,\n            raqib tomonidan urilgan gol sifatida hisoblanadi. ga tikishlarni hisoblash xususiyatlari\n            O'yinchining tennis ko'rsatkichi paragrafda ko'rsatilgan.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.10. O'ynamaydigan sport turlarida (chang'i, biatlon, yengil atletika va\n            va boshqalar) taqqoslashda \"Kim balandroq\" agar ishtirokchi (estafeta uchun)\n            - jamoa) boshladi, lekin tugatmadi, keyin unga pul tikdi\n            ular boshqa ishtirokchi bilan solishtirganda yutqazadilar. Agar ikkala ishtirokchi ham ketsa\n            masofadan yoki ishtirokchilardan biri boshlamagan bo'lsa - garovlar qaytariladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.11. Taymlar, davrlar, choraklar va boshqalar natijalariga garovlar\n            agar voqea haqiqiy emas deb topilgan bo'lsa, lekin birinchi yarmida (davr va\n            va hokazo) tugadi, keyin birinchi bo'limga garovlar odatdagidek hisob-kitob qilinadi\n            umuman voqeaga tikilgan tikishlar qaytarilsa ham buyurtma berish.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.12. U yoki bu voqea sodir bo'ladigan vaqtga tikish,\n            masalan, 1-golning vaqti, 1-kartaning vaqti, etakchilik vaqti\n            jamoalardan biri, va hokazo. Ordinal daqiqani taxmin qilish taklif etiladi, on\n            qaysi voqea sodir bo'ladi. Bunday stavkalarni hisoblash uchun aniq vaqt\n            soniyalarni hisobga olmagan holda aniqlanadi. Masalan, 1-golning vaqti, agar\n            Birinchi gol o'yin boshlanganidan 00 daqiqa 10 soniya o'tganida kiritildi - \"1-chi\"\n            daqiqa”, 04 min 10 sek – “5-daqiqa”, 04 min 59 sek – “5 daqiqa”,\n            05 daqiqa 00 soniya - \"6-daqiqa\".\n          </span>\n        </p>\n        <p>\n          <span>\n            4.13. Foizlarda ifodalangan ko'rsatkichlar bo'yicha garovlar (birinchi xizmatdan %,\n            to'pga egalik % va boshqalar) Hisoblash uchun indikatorning qiymati dan olinadi\n            arifmetika qoidalariga muvofiq butun songa yaxlitlangan rasmiy veb-sayt.\n          </span>\n        </p>\n        <p>\n          <span>\n            4.14. Bitta ko'rsatkich (p1) soniga tikish\n            boshqa indikator boshlanishidan oldin (p2). Masalan\n            &quot;birinchi gol oldidan nishonga berilgan zarbalar soni&quot;,\n            &quot;birinchi karta oldidagi qoidabuzarliklar soni&quot; va hokazo. Nishonga zarba berish\n            qaysi gol urilgani yoki ularga kartochka berilgan qoidabuzarlik hisoblanadi.\n            Agar gol yoki kartalar bo'lmasa, natija jami bo'ladi\n            ko'rsatkichlar soni p1 (ya'ni nishonga zarbalarning umumiy soni yoki\n            boshlar).\n          </span>\n        </p>\n        <p>\n          <span>5. Uchrashuv davomida garovlarni qabul qilish (jonli garovlar)</span>\n        </p>\n        <p>\n          <span>\n            5.1. Jonli garovlar asosiy va qo'shimcha natijalarga qabul qilinadi.\n            Siz bitta jonli pul tikishingiz yoki ularni bittaga birlashtirishingiz mumkin\n            ifodalash\n          </span>\n        </p>\n        <p>\n          <span>\n            5.2. Tikish serverda ro'yxatdan o'tgandan keyin qabul qilingan hisoblanadi va\n            onlayn tasdiqlash. Qabul qilingan tarifni o'zgartirish mumkin emas.\n            \"Asosiy.\" bo'limida ko'rsatilgan holatlar yuzaga kelganda\n            garovlarni qabul qilish qoidalari\" bo'limida jonli garovni koeffitsient bilan hisoblash mumkin\n            \"1\".\n          </span>\n        </p>\n        <p>\n          <span>\n            5.3. Bukmeker kontorlari har qanday noaniqliklar uchun javobgar emas\n            jonli garovlar qabul qilinadigan o'yinlarning joriy natijalari.\n            Mijozlar boshqa mustaqil manbalardan ham foydalanishlari kerak\n            ma'lumot.\n          </span>\n        </p>\n        <p>\n          <span>5.4. Jonli tikishlar tahrir qilinmaydi yoki o'chirilmaydi.</span>\n        </p>\n        <p>\n          <span>\n            6. Uchrashuvlar natijalari, ularning boshlanish sanasi va vaqti, qaror qabul qilish tartibi\n            munozarali masalalar\n          </span>\n        </p>\n        <p>\n          <span>\n            6.1. Noto'g'ri hisob-kitoblar tufayli tariflar qayta ko'rib chiqilishi mumkin\n            natija bukmeker tomonidan taqdim etiladi. Tikishlarni hisoblashda\n            hodisalarning haqiqiy boshlanish vaqti hisobga olinadi, qaysi\n            taxminan rasmiy hujjatlar asosida aniqlanadi\n            sport musobaqalarini o'tkazuvchi tashkilotlar va agar ular bo'lmasa\n            tasdiqlangan hujjatlar, keyin rasmiy veb-saytlar asosida\n            sport federatsiyalari, sport klublari veb-saytlari va boshqa manbalar\n            sport ma'lumotlari.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.2. Bukmeker kompaniyasi javobgar emas\n            sana va vaqt va voqealarning haqiqiy boshlanishi o'rtasidagi nomuvofiqlik. Sana va vaqt\n            Satrda ko'rsatilgan voqealarning boshlanishi ko'rsatkichdir.\n            Gamblinglarni hisoblashda tadbirning haqiqiy boshlanish vaqti hisobga olinadi,\n            rasmiy hujjatlar asosida belgilanadi\n            musobaqani o'tkazuvchi tashkilot.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.3. Bukmeker kontorlari har qanday noaniqliklar uchun javobgar emas\n            chempionatlarning nomlari va o'yinlar davomiyligi (sport\n            voqealar). Satr va jonli efirda ko'rsatilgan ma'lumotlar\n            indikativ xarakterga ega. Mijozlar boshqalardan foydalanishlari kerak\n            to'g'risidagi ma'lumotlarni aniqlashtirish uchun mustaqil axborot manbalari\n            sport tadbiri. Tadbir natijasi bo'yicha da'volar qabul qilinadi\n            agar rasmiy shaxslar mavjud bo'lsa, tadbir tugaganidan keyin 10 kun ichida\n            o'tkazuvchi tashkilot tomonidan chiqarilgan tadbir natijalari to'g'risidagi hujjatlar\n            raqobat.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.4. Tadbir boshlangandan keyin qo'yilgan garovlar bilan hisob-kitob qilinadi\n            “1” koeffitsienti (jonli garovlardan tashqari); tezyurar poyezdlarda\n            Bunday garovlar uchun koeffitsient \"1\" ga teng deb hisoblanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.5. Agar mijoz biror voqeaga pul tikgan bo'lsa, natijada u\n            ma'lum edi, bunday stavka bekor qilinishi kerak. Bu holda yechim\n            bukmeker kompaniyasi maxsus yopilgandan keyin qabul qilinadi\n            tergovlar. Bunday stavka bo'yicha barcha harakatlar vaqtinchalik\n            to'xtatilgan. &#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            6.6. Agar ishtirokchi tadbir boshlanishidan oldin jang qilishdan bosh tortsa, unda hamma\n            ushbu ishtirokchiga tikilgan garovlar bekor bo'ladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.7. Agar ishtirokchi biron bir sababga ko'ra (shikastlanish, rad etish va h.k.)\n            musobaqa davomida yo'q qilinadi, keyin barcha garovlar boshlanishidan oldin qo'yiladi\n            u ishtirok etgan tanlovning oxirgi bosqichi yoki bosqichi,\n            haqiqiy hisoblanadi va boshqa garovlar bekor hisoblanadi.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            6.8. Agar ishtirokchi, jamoa a'zosi (futbolchi, xokkeychi, basketbolchi).\n            h.k.) o'yinda qatnashmagan, tikish bo'yicha yutuq koeffitsienti\n            agar boshqacha ko'rsatilmagan bo'lsa, u \"1\" ga teng deb hisoblanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.9. Agar tennis o'yinida oldin rad etish (diskvalifikatsiya) sodir bo'lsa\n            o'yin boshlanishi bilan garovlar bo'yicha yutuq koeffitsientlari teng deb hisoblanadi\n            “1”, ishtirokchining musobaqadagi natijasiga tikilgan garovlar bundan mustasno. Agar\n            tennis o'yini to'xtatilgan, o'sha kuni yakunlanmagan va keyinga qoldirilgan, garovlar\n            u bo'lgan turnir oxirigacha amal qiladi\n            o'yin o'yin yakunlanmaguncha yoki rad etish sodir bo'lgunga qadar o'ynaldi\n            ishtirokchilardan biri.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            6.10. Agar biron bir hodisa (o'yin, musobaqa yoki jang) bo'lsa\n            ishtirokchilar juftligi (jamoalar, sportchilar) va keyinchalik juftlikning tarkibi\n            o'zgartirilsa, o'sha voqeaga tikilgan barcha garovlar bekor bo'ladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.11. Jamoa musobaqalarida, bir yoki bir nechtasini almashtirishda\n            har qanday sababga ko'ra jamoalarning har qanday ishtirokchisi, butun natijaga tikish\n            mosliklar haqiqiyligicha qoladi.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            6.12. Juftlik o'yinlarida, agar juftliklar tarkibi ko'rsatilgan bo'lsa, hech bo'lmaganda almashtirishda\n            ishtirokchilardan biri, tikish uchun yutuq koeffitsienti teng bo'ladi\n            \"1\". Agar tarkib ko'rsatilmagan bo'lsa, garovlar o'z kuchida qoladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.13. Musobaqalarda \"mezbonlar\" tushunchalari va\n            \"mehmonlar\", tadbir o'tkazilganda: neytral maydonga - garovlar\n            kuchli qoling; raqib jamoa maydonida - garovlar o'z kuchida qoladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.14. Agar \"mezbonlar\" va \"mehmonlar\" tushunchalari tadbirga taalluqli bo'lmasa\n            (masalan, yakkalik va juftlik sportida), keyin o'zgarganda\n            voqea joyi, unga barcha tikishlar o'z kuchini saqlab qoladi. Jamoalar\n            NBA, NHL, AHL, CHL, OHL, WHL, Sharqiy qirg'oq xokkey ligasi\n            Shimoliy Amerika to'g'ridan-to'g'ri ketma-ketlikda joylashtirilishi mumkin\n            (mezbonlar - mehmonlar) va aksincha. Teskari tartibga solish holatida\n            Gamblinglar uchun pul qaytarilmaydi.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.15. bilan klub o'rtoqlik turnirlarining o'rtoqlik uchrashuvlarida\n            Tadbir o'tkaziladigan joy o'zgarganda, unga tikilgan barcha garovlar o'zgarishsiz qoladi\n            kuch.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.16. Sport yoki alohida bo'lmagan holatlar\n            garovlarni qabul qilish va hisoblash xususiyatlarining tavsiflari umumiy bo'ysunadi\n            qoidalar.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.17. Presedentsiz bahsli vaziyatlarda final\n            qaror bukmekerlik kompaniyasi tomonidan qabul qilinadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            6.18. Turli manbalardan olingan ma'lumotlarning nomuvofiqligi\n            ma'lumot (sana, vaqt, natija, jamoa nomi)\n            Bukmeker kompaniyasi yutuqni to'lashni to'liq to'lagunga qadar to'xtatadi\n            bunday ma'lumotlarning haqiqiyligini tekshirish. Natija bo'lsa\n            rasmiy veb-saytida taqdim etilgan yakunlangan tadbir,\n            teleko'rsatuv ma'lumotlaridan farq qiladi, Kompaniya tark etadi\n            televideniye ma'lumotlari asosida hisob-kitob qilish huquqini o'zida saqlab qoladi\n            translyatsiyalar.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            6.19. If an error is detected in the coefficient output program and\n            recognition of this error by the company, all bets placed on these\n            events are considered winning and bets are paid out with\n            yutuq koeffitsienti \"1\" ga teng.\n          </span>\n        </p>\n        <p>\n          <span>7. Parties&#160;</span>\n        </p>\n        <p>\n          <span>\n            7.1. Shartnomaning barcha bandlari, shu jumladan “biz”, “biz” olmoshlari,\n            \"bizning\" yoki \"kompaniya\" mijoz bilan bo'lgan kompaniyani anglatadi\n            yuqoridagi 1-bandga muvofiq shartnoma tuzadi.\n          </span>\n        </p>\n        <p>\n          <span>8. Shartlarning o'zgarishi</span>\n        </p>\n        <p>\n          <span>\n            8.1. Bir qator sabablarga ko'ra, xususan: tijorat, yuridik, shuningdek\n            mijozlarga xizmat ko'rsatish bilan bog'liq sabablar, biz huquqiga egamiz\n            Shartnomaga har qanday o'zgartirishlar kiritish. Shartnomaning joriy bandlari va\n            ularning amal qilish sanalari veb-saytda keltirilgan. Mijoz shaxsiy javobgarlikni oladi\n            amaldagi Shartnoma bilan tanishish uchun javobgarlik. U\n            Kompaniya veb-sayt ishiga o'zgartirishlar kiritish huquqiga ega\n            istalgan vaqtda va mijozlarni oldindan xabardor qilmasdan.\n          </span>\n        </p>\n        <p>\n          <span>\n            8.2. Shartnomaning o'zgartirilgan bandlari bilan rozi bo'lmagan taqdirda, Buyurtmachi\n            veb-saytdan foydalanishni to'xtatishi kerak. Keyinchalik foydalanish\n            Veb-sayt, Shartnomaning o'zgartirilgan bandlari kuchga kirgandan so'ng,\n            dan qat'i nazar, to'liq qabul qilingan deb hisoblanadi\n            Mijoz tegishli bildirishnoma olganmi yoki bilib olganmi\n            yangilangan Shartnomadagi o'zgarishlar.\n          </span>\n        </p>\n        <p>\n          <span>9. Da'vo qilish huquqi</span>\n        </p>\n        <p>\n          <span>\n            9.1. 21 yoshga to'lmagan yoki yoshga to'lmagan shaxslar (keyingi o'rinlarda deb yuritiladi).\n            Ruxsat etilgan yosh), bu qonun uchun majburiydir\n            muayyan yurisdiktsiya qonunlariga muvofiq qimor o'yinlarida ishtirok etish\n            (21 yoshdan katta bo'lsa) veb-saytdan foydalanish taqiqlanadi.\n            Ruxsat etilgan yoshga to'lmagan shaxslar tomonidan veb-saytdan foydalanish\n            Shartnomani bevosita buzish hisoblanadi. Shu munosabat bilan bizda\n            tasdiqlashi mumkin bo'lgan hujjatlarni istalgan vaqtda talab qilish huquqiga ega\n            mijozning yoshi va shaxsiyati. Mijoz rad etilishi mumkin\n            xizmatlar ko'rsatish, uning hisobi to'xtatilishi mumkin\n            yoki tugatilgan bo'lsa, garovlar va yutuqlar bekor qilinadi va qolgan mablag'lar\n            agar bizning iltimosimiz bo'yicha ular taqdim etilmasa, qaytarilmasdan ushlab turiladi\n            mijozning yoshi mos ekanligini tasdiqlovchi dalil\n            Qabul qilinadi yoki Mijoz erishmaganligi aniqlansa\n            Yosh chegarasi. &#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            9.2. Onlayn qimor ayrim yurisdiktsiyalarda noqonuniy hisoblanadi.\n            Shartnomani qabul qilib, Mijoz Kompaniya qila olmasligini tushunadi\n            kafolatlar yoki huquqiy maslahatlar berish\n            yurisdiktsiya hududida Veb-saytdan foydalanishning qonuniyligi, in\n            mijoz qaerda joylashgan. Biz xizmatlarni da'vo qila olmaymiz\n            Veb-sayt Mijoz yurisdiktsiyasi qonunlarini buzmaydi. Mijoz foydalanadi\n            o'z iltimosiga binoan veb-sayt xizmatlarini to'liq o'z zimmasiga oladi\n            mas'uliyat, barcha mumkin bo'lgan xavflarni yaxshi bilish.\n          </span>\n        </p>\n        <p>\n          <span>\n            9.3. Biz Mijozga xizmatlar ko'rsatishga intilmaymiz va taqdim qilmoqchi emasmiz\n            o'z yurisdiktsiyasi qonunlarini buzish. Shartnomani qabul qilib,\n            Mijoz veb-saytdan foydalanishni tasdiqlaydi va kafolatlaydi\n            o'z hududida amaldagi qonunlar va qoidalarga amal qiladi\n            yurisdiktsiya. Biz noqonuniy foydalanish uchun javobgar emasmiz\n            veb-sayt xizmatlari.\n          </span>\n        </p>\n        <p>\n          <span>\n            9.4. Yuridik sabablarga ko'ra biz quyidagi mijozlarni qabul qilmaymiz\n            mamlakatlar:\n          </span>\n        </p>\n        <p>\n          <span>\n            9.4.1. Mutlaq cheklash. AQShdan kelgan mijozlar qabul qilinmaydi\n            Kanada, Buyuk Britaniya, Ispaniya, Latviya, Litva, Gollandiya,\n            Frantsiya, Italiya, Shveytsariya, Albaniya, Barbados, Pokiston, Suriya,\n            Janubiy Sudan, Kayman orollari, Gaiti, Yamayka, Shimoliy Koreya,\n            Malta va Panama. Hududda yashovchi yoki yashovchi shaxslar\n            bu mamlakatlarda hisob ochish yoki pul mablag'larini joylashtirishga ruxsat berilmaydi\n            veb-saytdagi mablag'lar. Yurisdiktsiyalar ro'yxati o'zgarishi mumkin va ular\n            Kompaniya tomonidan oldindan ogohlantirmasdan ishlab chiqarilishi mumkin\n            Mijozlar. Siz hisob ochmasligingizga rozilik bildirasiz yoki\n            birining hududida bo'lganida unga mablag'larni o'tkazish\n            yuqoridagi yurisdiktsiyalardan.\n          </span>\n        </p>\n        <p>\n          <span>\n            9.4.2. Qora roʻyxat. 9.4.1-bandga qo'shimcha ravishda, barcha NetEnt o'yinlari\n            quyidagi mamlakatlarda taqiqlangan: Afg'oniston, Albaniya, Jazoir, Angola,\n            Avstraliya, Kambodja, Ekvador, Gayana, Gonkong, Indoneziya, Eron,\n            Iroq, Isroil, Quvayt, Laos, Myanma, Namibiya, Nikaragua, Shimoliy\n            Koreya, Pokiston, Panama, Papua-Yangi Gvineya, Filippin, Singapur,\n            Janubiy Koreya, Sudan, Suriya, Tayvan, Uganda, Yaman, Zimbabve,\n            Belgiya, Bolgariya, Daniya, Estoniya, Latviya, Litva, Chexiya, Meksika,\n            Portugaliya, Ruminiya.\n          </span>\n        </p>\n        <p>\n          <span>9.4.3. Brendli oʻyinlar uchun cheklovlar.&#160;</span>\n        </p>\n        <p>\n          <span>\n            9.4.3.1. Games Guns & amp; Roses, Jimi Hendrix va Motörhead emas\n            quyidagi mamlakatlarda xizmat qilgan: Afg'oniston, Albaniya, Jazoir,\n            Angola, Kambodja, Ekvador, Gayana, Gonkong, Indoneziya, Eron, Iroq,\n            Quvayt, Laos, Myanma, Namibiya, Nikaragua, Shimoliy Koreya, Pokiston,\n            Panama, Papua-Yangi Gvineya, Filippin, Singapur, Janubiy Koreya, Sudan,\n            Suriya, Tayvan, Uganda, Yaman, Zimbabve, Belgiya, Bolgariya, Kanada,\n            Daniya, Estoniya, Fransiya, Italiya, Latviya, Litva, Meksika, Portugaliya,\n            Ruminiya, Ispaniya, Amerika Qo'shma Shtatlari, Buyuk Britaniya,\n            Avstraliya, Ozarbayjon, Xitoy, Hindiston, Malayziya, Qatar, Rossiya,\n            Tailand, Tunis, Turkiya va Ukraina.&#160;\n          </span>\n        </p>\n        <p>\n          <span>9.4.3.2. O'yinlar </span>Universal HAYVONLAR (Frankenshteyn, Kelin\n          Frankenshteyn, Drakula, Fantomning la'nati, Qora jonzot\n          Lagun va Ko'rinmas odam\n          <span>\n            ), FAQAT quyidagi mamlakatlarda xizmat ko'rsatiladi: Andorra,\n            Armaniston, Ozarbayjon, Belarus, Bosniya va Gertsegovina, Braziliya,\n            Gruziya, Islandiya, Lixtenshteyn, Moldova, Monako, Chernogoriya,\n            Norvegiya, Rossiya, San-Marino, Serbiya, Shveytsariya, Ukraina, Xorvatiya,\n            Makedoniya, Turkiya, Avstriya, Bolgariya, Kipr, Finlyandiya, Germaniya,\n            Gretsiya, Vengriya, Irlandiya, Lyuksemburg, Malta, Niderlandiya, Peru,\n            Polsha, Slovakiya, Sloveniya va Shvetsiya.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            9.4.4. Birlashtirilgan Jackpot chegaralari. Birlashtirilgan jackpotlar\n            qo'llab-quvvatlanmaydi va quyidagi mamlakatlarda mavjud bo'lmasligi mumkin:\n            Avstraliya, Ozarbayjon, Xitoy, Daniya, Hindiston, Isroil, Italiya,\n            Yaponiya, Malayziya, Qatar, Rossiya, Ispaniya, Tailand, Tunis, Turkiya,\n            Birlashgan Arab Amirliklari va Ukraina.\n          </span>\n        </p>\n        <p>\n          <span>9.5. Gamblinglar qabul qilinmaydi:</span>\n        </p>\n        <p>\n          <span>\n            9.5.1. qaysi tadbirlarda ishtirok etayotgan shaxslardan\n            tikish o'yinchilari (sportchilar, murabbiylar, hakamlar, klub egalari yoki amaldorlar).\n            va hodisaning natijasiga ta'sir qilish imkoniyatiga ega bo'lgan boshqa shaxslar), shuningdek\n            ularning nomidan ish yurituvchi shaxslardan; manfaatlarini ifodalovchi shaxslardan\n            boshqa bukmeker kompaniyalari;\n          </span>\n        </p>\n        <p>\n          <span>\n            9.5.2. bukmeker kontorlari bilan tuzilgan shartnomada ishtirok etgan boshqa shaxslardan\n            kompaniya amaldagi qonun hujjatlari bilan taqiqlangan.\n          </span>\n        </p>\n        <p>\n          <span>\n            9.6. Ushbu Shartnomaning 9.5-bandini buzganlik uchun javobgarlik\n            pul tikuvchi tomonidan to'lanadi. Ushbu Shartnoma buzilgan taqdirda,\n            bukmeker kompaniyasi to'lovni rad etish huquqini o'zida saqlab qoladi\n            har qanday yutuq yoki depozit qilingan summalarni qaytarish, shuningdek\n            har qanday garovlarni bekor qiling. Bukmekerlik kompaniyasi ko'tarmaydi\n            javobgarlik&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            mijoz kirayotganini aniq qachon bilganligi haqida\n            yuqorida sanab o'tilgan shaxslar toifalaridan biriga. Bu shuni anglatadiki\n            bukmeker kompaniyasi istalgan vaqtda ushbu choralarni ko'rishga haqli\n            mijozning biri ekanligi ma'lum bo'lganidan keyin vaqt o'tgach\n            belgilangan shaxslar.\n          </span>\n        </p>\n        <p>\n          <span>\n            9.7. Agar tikish o'yinchisiga nisbatan firibgarlik qilsa\n            bukmeker kompaniyasi (ko'p hisob, dasturiy ta'minotdan foydalanish\n            pul tikish avtomatlashtirish, arbitraj vaziyatlarda o'ynash, o'yin bo'lsa\n            hisob tikish, suiiste'mol qilish uchun foydalanilmaydi\n            sodiqlik dasturlari va boshqalar), keyin bukmekerlik kompaniyasi ketadi\n            bekor qilish orqali bunday firibgarlik faoliyatini to‘xtatish huquqini o‘zida saqlab qoladi\n            tikish va tikish ishtirokchisining o'yin hisobini yopish.\n          </span>\n        </p>\n        <p>\n          <span>10. &#160; hisobini ochish</span>\n        </p>\n        <p>\n          <span>\n            10.1. Barcha muhim xizmatlarga kirish uchun\n            Veb-sayt, siz hisob ochishingiz kerak. Buning uchun mijoz mumkin\n            \"1 marta bosishda\" ro'yxatdan o'ting yoki manzilingizni ko'rsating\n            elektron pochta xabarini yuboring va parolni o'ylab toping, bu keyinroq bo'ladi\n            o'yin profiliga kirish uchun ishlatiladi, shuningdek, qo'shimcha ravishda\n            Shaxsiy ma'lumotlar talab qilinadi: ism, telefon raqami va sana\n            tug'ilgan.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            10.2. Mijoz haqiqiy elektron pochta manzilini ko'rsatishi kerak\n            ro'yxatga olish jarayoni yoki \"1-klik\" ro'yxatdan o'tish holatida o'zgartirish\n            haqiqiy manzil.\n          </span>\n        </p>\n        <p>\n          <span>\n            10.3. Ma'lumotlarning to'g'riligini tasdiqlash uchun kompaniya bor\n            mijozning shaxsini tasdiqlovchi hujjatlarni talab qilish huquqi. Agar\n            ba'zi sabablarga ko'ra mijoz so'ralgan narsani taqdim etmaydi\n            shaxsni tasdiqlovchi hujjatlar, Kompaniya to'xtatib turish huquqiga ega yoki\n            mijozning profilini kerakli narsani taqdim qilmaguncha bloklash\n            ma'lumot.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            10.4. Mijoz veb-saytda ro'yxatdan o'tish paytida u ekanligini tasdiqlaydi\n            o'zi to'g'risida to'liq va aniq ma'lumot ko'rsatdi va shunday bo'lsa\n            unda har qanday o'zgarishlar yuz bersa, mijoz o'z zimmasiga oladi\n            Ularni darhol profilingizga qo'shing. Mos kelmaslik yoki\n            ushbu qoidani e'tiborsiz qoldirish arizaga olib kelishi mumkin\n            cheklovlar, profilni to'xtatib turish yoki blokirovka qilish, shuningdek\n            to'lovlarni bekor qilish.\n          </span>\n        </p>\n        <p>\n          <span>\n            10.5. Agar sizda biron bir savol yoki muammo bo'lsa\n            Saytda ro'yxatdan o'tgandan so'ng, mijoz qo'llab-quvvatlash xizmatiga murojaat qilishi mumkin\n            onlayn chat yoki qo'ng'iroq orqali – 8 (800) 301-77-89\n            (soat bo'yi).\n          </span>\n        </p>\n        <p>\n          <span>\n            10.6. Har bir mijoz saytda faqat bitta hisob ochishi mumkin.\n            Mijoz tomonidan ochilgan boshqa hisoblar dublikat hisoblanadi. Bizda bor\n            bunday hisoblarni yopish va haqiqiy emas deb topish huquqi mavjud\n            dublikat hisobi yordamida amalga oshirilgan barcha operatsiyalar.\n          </span>\n        </p>\n        <p>\n          <span>\n            10.6.1. Mijozlarga barcha omonat va pul tikishlarini qaytarib bermang\n            asosiy va zaxira hisoblar; hammaning qaytishini talab qiladi\n            yutuqlar, bonuslar va foydalanish paytida olingan naqd pul\n            dublikat hisob. Mijoz ularni birinchi navbatda qaytarishi shart\n            talab.&#160;\n          </span>\n        </p>\n        <p>\n          <span>11. Shaxsni tasdiqlash. Legalization&#160;</span>\n        </p>\n        <p>\n          <span>\n            11.1 Iltimos, ism va tug'ilgan sanani unutmang.\n            profilingizda ko'rsatilgan ma'lumotlar sizga mos kelishi kerak\n            haqiqiy ism.\n          </span>\n        </p>\n        <p>\n          <span>\n            11.2 Ro'yxatdan o'tish paytida profilingizda ko'rsatilgan ism bo'lishi kerak\n            kredit kartadagi yoki boshqa toʻlov profilidagi nomga mos kelish;\n            o'yiningizdan pul mablag'larini to'ldirish yoki yechib olish uchun ishlatiladi\n            hisob.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.3 Sizning shaxsingizni, manzilingizni va/yoki to'lovni tasdiqlash uchun\n            profil (shaxs) biz istalgan vaqtda so'rashimiz mumkin: &#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.3.1. proof of identity (including, but not limited to, copies\n            amaldagi pasport/identifikator va/yoki foydalanilgan\n            to'lov kartalari),\n          </span>\n        </p>\n        <p>\n          <span>\n            11.3.2. manzilni tasdiqlovchi hujjat, shu jumladan, lekin ular bilan cheklanmagan holda\n            kommunal to'lovlar (uch oydan ko'p bo'lmagan).\n            retsept), &#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.3.3 Tanlanganlarga tegishli hisobvaraqlar holati to'g'risida bankdan ma'lumotnoma\n            to'lov usuli (uch oydan ortiq bo'lmagan).\n          </span>\n        </p>\n        <p>\n          <span>\n            11.4 Agar siz bizga ushbu hujjatlarni taqdim etmasangiz va/yoki biz buni qila olmasak\n            o'rtacha vaqt ichida shaxsingizni tasdiqlang,\n            biz belgilagan, biz huquqni saqlab qolamiz; &#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.4.1 Mijozning profilini tekshirishgacha bloklash\n            muvaffaqiyatli yakunlanadi;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.4.2 tranzaktsiyalaringizning hammasini yoki bir qismini bekor qilish\n            va profilingizni muzlatib qo'ying va/yoki profilingizni muzlatib qo'ying yoki yoping va\n            ushbu Shartnomani bekor qilish.\n          </span>\n        </p>\n        <p>\n          <span>\n            11.5 Biz xavfsizlik tekshiruvlarini o'tkazish huquqini saqlab qolamiz\n            shaxsingiz, yoshingiz haqidagi ma'lumotlarni tasdiqlash uchun istalgan vaqtda\n            va siz taqdim etgan boshqa ro'yxatga olish yoki to'lov ma'lumotlari\n            Xizmatlardan foydalanganingizni tekshirish uchun (masalan, to\n            Taqiqlangan faoliyatning oldini olish), bunga rioya qilishingiz\n            Sizning moliyaviy operatsiyalaringiz bo'yicha kelishuvlar va cheklar\n            Xizmatlardan foydalanish doirasida, buning mumkin bo'lgan buzilishi uchun\n            Shartnomalar.\n          </span>\n        </p>\n        <p>\n          <span>\n            11.6 Siz bukmekerga har qanday so'rov qilish huquqini berasiz\n            sizga nisbatan, foydalanish va har qanday uchinchi shaxsga oshkor qilish\n            uni tekshirish maqsadida siz haqingizda har qanday ma'lumot.\n          </span>\n        </p>\n        <p>\n          <span>\n            11.7 Siz bizning so'rovimizga ko'ra har qanday narsani taqdim etishga rozilik bildirasiz\n            audit o'tkazish uchun qo'shimcha ma'lumotlar yoki hujjatlar\n            xavfsizlik.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            11.8 Ushbu protsedura majburiy talab bo'lib, unda amalga oshiriladi\n            joriy qimor qoidalariga muvofiq va\n            jinoiy daromadlarni legallashtirishga qarshi kurashish bo'yicha qonuniy talablar, shu jumladan\n            to'g'risidagi Milliy Nizomga muvofiq, xususan\n            nostandart operatsiyalar va bizning ichki ishlarimiz haqida ma'lumot berish\n            jinoiy daromadlarni legallashtirishga va oldini olishga qarshi siyosat\n            terrorizmni moliyalashtirish.\n          </span>\n        </p>\n        <p>\n          <span>12. Foydalanuvchi nomi, parol va xavfsizlik</span>\n        </p>\n        <p>\n          <span>\n            12.1. Veb-saytda hisob ochgandan so'ng, Mijoz o'z hisobini saqlashi shart\n            parol va foydalanuvchi nomi sir saqlanadi va oshkor etilmaydi\n            uchinchi shaxslarga ma'lumot. uchun zarur bo'lgan ma'lumotlar yo'qolgan taqdirda\n            hisob qaydnomasiga kirish, ularni bosish orqali bilib olishingiz yoki tiklashingiz mumkin\n            \"Parolni tiklash\" tugmasini bosing.\n          </span>\n        </p>\n        <p>\n          <span>\n            12.2. Mijoz parolning xavfsizligi, shuningdek, har qanday harakatlar uchun javobgardir\n            va uning hisobi bilan amalga oshirilgan operatsiyalar. Bundan tashqari, Mijoz o'z zimmasiga oladi\n            uning harakatlari natijasida etkazilgan barcha zararlar uchun javobgarlik\n            uchinchi tomon.\n          </span>\n        </p>\n        <p>\n          <span>\n            12.3. Xavfsizlik buzilishi va ruxsatsiz kirish holatlarida\n            hisobiga Mijoz darhol bukmekerni xabardor qilishi kerak\n            kompaniya. Agar kerak bo'lsa, mijoz kompaniyaga taqdim etishi shart\n            ruxsatsiz kirishning haqiqiyligini tasdiqlovchi dalil\n            sodir bo'ldi. Bukmeker kompaniyasi zarar uchun javobgar emas\n            noto'g'ri yoki ehtiyotsizlik natijasida mijoz tomonidan olingan\n            foydalanuvchi nomi va paroldan uchinchi shaxs tomonidan yoki uchun foydalanish\n            hisob qaydnomasiga ruxsatsiz kirish.\n          </span>\n        </p>\n        <p>\n          <span>\n            13. Hisobvaraqdan pul mablag'larini kiritish, joylashtirish va yechib olish\n          </span>\n        </p>\n        <p>\n          <span>\n            13.1. Veb-saytga pul tikish uchun Mijoz shart\n            hisobingizga ma'lum miqdorda pul qo'ying.\n          </span>\n        </p>\n        <p>\n          <span>13.2. Mijoz quyidagilarni tasdiqlaydi va majburiyatini oladi:</span>\n        </p>\n        <p>\n          <span>\n            13.2.1. o'yin hisobiga kiritilgan mablag'lar yo'q edi\n            noqonuniy yoki taqiqlangan vositalar orqali olingan;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.2.2. Mijoz tugallangan tranzaktsiyalarni rad etmaydi\n            bo'lishi mumkin bo'lgan to'lovlarni rad etadi va bekor qiladi\n            pulni uchinchi shaxsga qaytarish va ularga qutulish uchun sabab\n            huquqiy javobgarlik.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.3. Biz uchinchi shaxslardan mablag'larni qabul qilmaymiz: do'stlar,\n            qarindoshlar yoki sheriklar. Mijoz pul mablag'larini depozitga qo'yishi shart\n            faqat hisobingizdan, bank kartangizdan yoki tizimingizdan,\n            mijoz nomiga ro'yxatdan o'tgan. Agar faktlar oshkor etilsa\n            Ushbu shartni buzgan holda, barcha yutuqlar musodara qilinishi mumkin.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.4. Pulni qaytarish uchun bank o'tkazmasini talab qilgan taqdirda\n            mablag'lar qonuniy egasiga, barcha xarajatlar va komissiyalar to'lanadi\n            oluvchi hisobidan.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.5. Biz naqd to'lovlarni qabul qilmaymiz. Biz\n            elektron to'lovlar, shu jumladan kirish uchun foydalanish mumkin\n            Mijozlarga, turli tashkilotlarga to'lovlar va to'lovlar\n            elektron to'lov protsessorlari yoki moliya institutlari. uchun\n            ushbu muassasalarning qoidalari va shartlari bundan mustasno\n            Shartnoma shartlariga zid bo'lsa, Mijoz buni to'liq qabul qiladi\n            qoidalari.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.6. Mijoz rad etmaslik, bekor qilmaslik yoki\n            hisob qaydnomasi yordamida amalga oshirilgan operatsiyalarni bekor qilish. Bundan tashqari, in\n            Bunday holatlarning har birida Mijoz qaytarib berishga yoki kompensatsiya to'lashga majburdir\n            Kompaniyaning joylashtirilmagan mablag'lari miqdori, shu jumladan xarajatlar,\n            Mijoz depozitlarini yig'ishda biz duch kelishimiz mumkin.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.7. Kompaniya Mijozning hisobini bloklash huquqiga ega, shuningdek\n            to'lovlarni bekor qiling va agar mavjud bo'lsa, yutuqni qaytarib oling\n            hisobni to‘ldirganligi haqidagi shubhalar\n            firibgarlik yo'lida. Biz tegishli shaxslarni xabardor qilishga haqlimiz\n            to'lov firibgarlik va noqonuniy haqida organlari\n            tadbirlar. Biz yig'ish xizmatlaridan foydalanish huquqiga egamiz\n            to'lovlarni qaytarish uchun agentliklar. Kompaniya javobgar emas\n            nima bo'lishidan qat'i nazar, kredit kartalaridan ruxsatsiz foydalanish\n            ular o'g'irlanganmi yoki yo'qmi.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.8. Biz Mijoz hisobidagi ijobiy qoldiqdan foydalanish huquqiga egamiz\n            Mijoz qaytarishi kerak bo'lgan pul miqdorini to'lash\n            Kompaniyalar. Xususan, takroriy tikish yoki tikish holatlarida, ko'ra\n            10-band (\"Tirikish, aldamchi harakatlar, firibgarlik\"\n            va jinoiy faoliyat) yoki 13-band (\"Xatolar va\n            kamchiliklar\") &#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.9. Mijoz o'yinni to'liq biladi va buni qabul qiladi\n            hisob bank hisobi emas. Shuning uchun, nisbatan\n            sug'urtalash usullari, to'ldirish, kafolatlar va boshqa usullar unga taalluqli emas\n            depozitlarni sug'urtalash tizimidan himoya qilish usullari va boshqalar\n            sug'urta tizimlari. O'yin hisobidagi mablag'lar emas\n            foizlar undiriladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.10. Mijoz qachon hisobdan pul yechib olish to'g'risida so'rov yuborish huquqiga ega\n            sharti bilan:\n          </span>\n        </p>\n        <p>\n          <span>\n            13.10.1 Hisobga tushgan barcha to'lovlar tekshirilgan, birortasi ham emas\n            bekor qilinmagan yoki bekor qilinmagan;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.10.2 tekshirish harakatlari to'g'ri bajarilgan.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.11. Hisobvaraqdan pul mablag'larini olish uchun arizani rasmiylashtirishda bo'lishi kerak\n            quyidagi fikrlar hisobga olinadi:\n          </span>\n        </p>\n        <p>\n          <span>13.11.1. o'yin profili to'liq to'ldirilgan bo'lishi kerak;</span>\n        </p>\n        <p>\n          <span>\n            13.11.2. agar so'ralgan pul olish operatsiyasining natijasi umumiy summa bo'lsa\n            pul mablag'larini olib qo'yish 50 000 rubldan oshadi. yoki\n            har qanday boshqa valyutadagi ekvivalent summada amalga oshiriladi\n            identifikatsiya qilish tartibi. Buni amalga oshirish uchun mijoz kerak\n            bizga hujjatning nusxasini yoki raqamli fotosuratini yuboring,\n            mijozni aniqlash. orqali hisobingizni to'ldirishda\n            kredit karta, siz ikkala tomonning rasmining nusxasini yuborishingiz kerak\n            bu karta. Birinchi oltita va\n            oxirgi to'rtta raqam, CVV2 kodi yashirilishi mumkin;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.11.3. kompaniya xarajatlarni qoplash uchun komissiya olish huquqiga ega;\n            o'yinda foydalanilmagan mablag'larni olib qo'yish bilan bog'liq;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.11.4. yechib olish miqdori 5000 rublgacha yoki unga teng miqdorda\n            boshqa valyuta, mijozning hisobiga 1 dan 60 daqiqagacha to'lanadi\n            texnik muammolar bundan mustasno, ariza topshirilgan paytdan boshlab\n            bank yoki to'lov tizimining tomonlari;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.11.5. yechib olish summasi 5000 rubldan yoki unga teng miqdorda\n            5 kun ichida mijozning hisob raqamiga to'langan boshqa valyuta\n            ariza berish vaqti;\n          </span>\n        </p>\n        <p>\n          <span>\n            11/13/6. Bunga qarab 3 ish kunigacha bo'lgan boshqa kechikishlar mumkin\n            bank yoki boshqa to'lov tizimidan;\n          </span>\n        </p>\n        <p>\n          <span>\n            11/13/7. yutuqni qaytarib olishning boshqa usullari alohida muhokama qilinadi\n            Veb-sayt ma'muriyati.&#160; bilan\n          </span>\n        </p>\n        <p>\n          <span>\n            13.12. Kompaniya pul ayirboshlash xizmatlarini taqdim etmaydi.\n            Biz bunday hisoblarni yopish huquqiga egamiz va:\n          </span>\n        </p>\n        <p>\n          <span>\n            13.12.1. biz olib chiqish xarajatlari miqdorida komissiya ushlab qolish\n            o'yinda ishtirok etmagan mablag'lar; &#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.12.2. bilan amalga oshirilgan barcha operatsiyalarni haqiqiy emas deb hisoblaydi\n            asosiy va dublikat hisoblardan foydalanish;\n          </span>\n        </p>\n        <p>\n          <span>\n            13.12.3. Mijozlarga asosiy va undan qo'yilgan barcha depozitlarni qaytarmaslik\n            dublikat hisoblar.\n          </span>\n        </p>\n        <p>\n          <span>\n            13.13 Pul mablag'larini yechib olishni faollashtirish uchun o'yinchi kerak\n            har bir kiritilgan depozitning kamida 100% miqdorida pul tikish\n            yoki qo'yilgan har bir depozitdan kamida 100% foydalaning\n            platformamizdagi har qanday o'yinlarda (o'ynang, foydalaning).\n          </span>\n        </p>\n        <p>\n          <span>\n            13.14. Agar yutuq miqdori 5 000 000 dan ortiq bo'lsa\n            (besh million rubl), bukmekerlik kompaniyasi zaxira qiladi\n            hisoblab chiqilgan kunlik chekinish chegarasini belgilash huquqi\n            har bir mijoz uchun alohida.\n          </span>\n        </p>\n        <p>\n          <span>14. Bukmekerlik xizmatlarini ko'rsatish shartlari:</span>\n        </p>\n        <p>\n          <span>\n            14.1. Siz barcha xizmatlar va/yoki tovarlar yoki boshqa narsalar uchun to'lashga rozilik bildirasiz\n            Siz tomonidan veb-saytda buyurtma qilingan qo'shimcha xizmatlar, shuningdek, barcha\n            qo'shimcha xarajatlar (agar kerak bo'lsa), shu jumladan, lekin emas\n            barcha turdagi soliqlar, yig'imlar va boshqalar bilan cheklangan. Siz to'liq ko'tarasiz\n            Barcha to'lovlarni o'z vaqtida to'lash uchun javobgarlik. Provayder\n            to'lov xizmatlari faqat belgilangan muddatda to'lov amalga oshirilishini ta'minlaydi\n            Veb-sayt hajmi va to'lov uchun javobgar emas\n            Veb-sayt foydalanuvchisi tomonidan yuqoridagi qo'shimcha summalar. Keyin\n            \"To'lov\" tugmasini bosish orqali to'lov amalga oshirilgan deb hisoblanadi,\n            va u qaytarib bo'lmaydigan tarzda amalga oshiriladi. \"To'lov\" tugmasini bosish orqali siz\n            to'lovni bekor qila olmasligingizga rozilik bildirasiz yoki\n            bekor qilishni talab qiladi. Saytda buyurtma berish orqali siz tasdiqlaysiz va\n            hech bir davlat qonunlarini buzmayotganligingizni bildiring.\n            Bundan tashqari, ushbu qoidalar qoidalarini (va/yoki Shartlar va\n            qoidalari), siz to'lov kartasi egasi sifatida buni tasdiqlaysiz\n            taklif qilingan tovarlar va/yoki xizmatlardan foydalanish huquqiga ega\n            Veb-sayt.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            14.2. Agar siz veb-sayt taklifining xizmatlaridan foydalansangiz\n            o'yin xizmatlari kabi maxsus xizmatlarni taqdim etasiz\n            erishganingiz yoki allaqachon ega bo'lganligingiz qonuniy majburiy tasdiq\n            qonuniy balog'at yoshidan oshgan\n            xizmatlardan foydalanish uchun yurisdiksiyangizda ruxsat berilgan\n            veb-sayt tomonidan taqdim etilgan.\n          </span>\n        </p>\n        <p>\n          <span>\n            14.3. Veb-sayt xizmatlaridan foydalanishni boshlash bilan siz o'z zimmangizga olasiz\n            har qanday qonunlarga rioya qilish uchun yuridik javobgarlik\n            ushbu xizmatdan foydalaniladigan mamlakatlar va buni tasdiqlang\n            To'lov xizmati provayderi hech qanday javobgarlikni o'z zimmasiga olmaydi\n            noqonuniy yoki ruxsatsiz shunga o'xshash buzilish. Rozilik\n            Veb-sayt xizmatlaridan foydalaning, siz buni tushunasiz va qabul qilasiz\n            To'lovlaringizning har qandayiga ishlov berish to'lov provayderi tomonidan amalga oshiriladi\n            xizmatlar va allaqachon sotib olingan narsalarni qaytarish uchun qonuniy huquq yo'q.\n            xizmatlar va/yoki tovarlar yoki boshqa toʻlovlarni bekor qilish imkoniyatlari. Agar siz\n            keyingi xaridingiz uchun xizmatdan foydalanishni to‘xtatmoqchi\n            xizmatlar va/yoki tovarlar bo'lsa, xizmatdan foydalanishni rad etishingiz mumkin\n            Veb-saytdagi shaxsiy hisob.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            14.4. To'lov xizmati provayderi javobgar emas\n            to'lovingiz bilan bog'liq ma'lumotlarni qayta ishlashni rad etish/qobiliyatsizlik\n            karta, yoki emitent bankdan olinmaganligi sababli rad etish uchun\n            to'lov kartangiz yordamida to'lovni amalga oshirish uchun ruxsat\n            kartalar. To'lov xizmati provayderi javobgar emas\n            Sizga taklif etilayotgan har qanday xizmat va/yoki mahsulot sifati, hajmi, narxi\n            yoki toʻlov kartangizdan foydalangan holda veb-saytingizda sotib olingan.\n            Veb-saytning har qanday xizmatlari va/yoki tovarlari uchun haq to'lash orqali siz, birinchi navbatda,\n            veb-saytdan foydalanish qoidalariga rioya qilishlari shart. Iltimos, hisobga oling\n            faqat siz to'lov kartasi egasi sifatida javobgarsiz\n            siz buyurtma bergan har qanday xizmat va/yoki mahsulotning o'z vaqtida to'lovi uchun\n            Veb-sayt orqali va bu bilan bog'liq barcha qo'shimcha to'lovlar uchun\n            xarajatlar/komissiyalar. To'lov xizmati provayderi faqat\n            to'lov ijrochisi veb-sayt tomonidan belgilangan miqdorda va hech qanday o'z zimmasiga olmaydi\n            har qanday narxlash, umumiy narxlar va/yoki umumiy javobgarlik\n            summalari.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            14.5. Agar sizning kelishmovchiligingiz bilan bog'liq vaziyat yuzaga kelsa\n            yuqoridagi shartlar va/yoki boshqa sabablar bilan sizdan so'raymiz\n            to'lovni o'z vaqtida to'lashdan bosh tortish va kerak bo'lganda,\n            to'g'ridan-to'g'ri veb-sayt administratori/qo'llab-quvvatlash xizmatiga murojaat qiling.\n          </span>\n        </p>\n        <p>\n          <span>\n            15. Tijorat, noto'g'ri ma'lumot, Firibgarlik va\n            jinoiy faoliyat&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.1. Kompaniya mijozlar guruhiga pul tikishni tavsiya etmaydi\n            bitta IP-manzil yoki bir xil mahalliy tarmoqdan, shuningdek\n            oldindan tasdiqlash. Yuqoridagi qadamlar bo'lishi mumkin\n            fitna, firibgarlik, qo'zg'atuvchi harakatlar sifatida qaraladi\n            aldanish.\n          </span>\n        </p>\n        <p>\n          <span>\n            15.2. Kompaniya hech qanday javobgarlikni o'z zimmasiga olmaydi\n            u buni qachon aniq bilgan yoki keyin aniqlagan\n            garov qoidalarni buzgan holda tuzilgan. Biz yopish huquqiga egamiz\n            shunga o'xshash hisoblar va:&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.2.1. barcha operatsiyalarni bekor qilish, qaytarib bermaslik\n            Mijozlarga barcha depozitlar va garovlar boshqalar bilan kelishilgan holda amalga oshiriladi\n            Mijozlar;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.2.2. barcha yutuqlar, bonuslar va naqd pullarni qaytarishni talab qilish\n            fitna natijasida olingan mablag'lar. Mijoz qaytishga majbur\n            ularni bizning birinchi talabimiz bo'yicha.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.3. Quyidagi faoliyatlar qat'iyan man etiladi\n            bunday harakatlar bevosita huquqbuzarlik sifatida baholanadi\n            Shartnomalar: &#160;\n          </span>\n        </p>\n        <p>\n          <span>15.3.1. ma'lumotlarni uchinchi shaxsga o'tkazish;</span>\n        </p>\n        <p>\n          <span>\n            15.3.2. noqonuniy faoliyat: firibgarlik, ekspluatatsiya\n            zararli dasturlar, botlar va dasturiy xatolar\n            Veb-sayt; &#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.3.3. o'g'irlangan narsalarni ishlatish kabi firibgarlik faoliyati,\n            klonlangan yoki boshqa noqonuniy yo'l bilan olingan kredit ma'lumotlari\n            yoki hisobingizni to'ldirish uchun debet kartasi;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.3.4. jinoiy faoliyatda ishtirok etish, pul yuvish va boshqalar\n            ishtirok etishi mumkin bo'lgan faoliyat\n            jinoiy javobgarlik;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.4. Biz to'xtatib turish, bekor qilish yoki olib tashlash huquqiga egamiz\n            bonus mablag'lari bilan bog'liq to'lovlar yoki yutuqlar, shu jumladan\n            agar biz mijozning qasddan ekanligiga shubha qilsak\n            ularni suiiste'mol qiladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            15.5. Kompaniya barcha ruxsat etilgan va qonun bilan ruxsat etilgan narsalarni oladi\n            yolg'on fitnalarni istisno qilish va aniqlash bo'yicha harakatlar va ularning\n            bevosita ishtirokchilar, shuningdek, majburiy ravishda ushbu shaxslarga qarshi\n            Tegishli choralar ko'riladi. Biz olib ketmaymiz\n            natijasida Mijozlar tomonidan olingan yo'qotishlar va zararlar uchun javobgarlik\n            firibgarlik faoliyati.\n          </span>\n        </p>\n        <p>\n          <span>\n            15.6. Mijozlar, agar mavjud bo'lsa, darhol bizga xabar berishlari kerak\n            har qanday mijozda shubha tug'iladi\n            til biriktirib yoki firibgarlik faoliyatini amalga oshiradi.\n            Veb-sayt orqali xizmatga murojaat qilish orqali biz bilan bog'lanishingiz mumkin\n            onlayn chat yoki qo'ng'iroq orqali qo'llab-quvvatlash - 8 (800)\n            301-77-89 (24 soat).&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.7. Biz oldindan ogohlantirmasdan taqiqlash huquqiga egamiz\n            Mijozlar veb-saytga kirishadi va o'z hisoblarini bloklaydilar\n            agar ular firibgarlik faoliyatida gumon qilinsa. Bunday holda\n            Biz qaytarish va kompensatsiya uchun javobgar bo'lmagan hollarda\n            bunday Mijozlarning hisobvaraqlarida mavjud bo'lgan mablag'lar. Bundan tashqari, at\n            biz huquq-tartibot idoralarini noqonuniy ravishda xabardor qilishga haqlimiz\n            tadbirlar. Mijozlar biz bilan to'liq hamkorlik qilishlari kerak\n            bunday holatlarni tekshirish.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.8. Mijozlarga xizmatlar va dasturlardan foydalanish taqiqlanadi\n            har qanday firibgarlik, noqonuniy ishlarni amalga oshirish uchun veb-saytni taqdim etish\n            har qanday qonun hujjatlariga muvofiq harakatlar va bitimlar\n            maxsus yurisdiktsiya. Agar biror fakt aniqlansa yoki aniqlansa\n            Mijoz bunday harakatlarni sodir etgan bo'lsa, Kompaniya buni qilishi mumkin\n            mijozning hisobini to'xtatib qo'yish yoki bloklash va pul mablag'larini ushlab turish,\n            unda mavjud. Bunday hollarda Mijozlar taqdim etish huquqiga ega emaslar\n            Kompaniya har qanday da'volar.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            15.9. nomidan o'yin faoliyatini amalga oshirish taqiqlanadi\n            uchinchi shaxslar (o'yin hisobining nominal egalari).\n          </span>\n        </p>\n        <p>\n          <span>\n            Agar o'yin profili darhol bloklanishi mumkin\n            xizmat xodimi tomonidan o'yin profilini tekshirish jarayoni\n            xavfsizlik tekshiruvdan o'tayotgan shaxs emasligi aniqlanadi\n            sport tikish sohasida yetarli bilimga ega\n            voqealar.&#160;\n          </span>\n        </p>\n        <p>\n          <span>16. &#160; veb-saytida boshqa taqiqlangan harakatlar</span>\n        </p>\n        <p>\n          <span>\n            16.1. Agressiv yoki foydalanish taqiqlanadi\n            tajovuzkor muloqot usuli, haqoratli so'zlar, tahdidlar va\n            xodimlarga nisbatan har qanday zo'ravonlik harakatlarini qo'llash va\n            Kompaniyaning boshqa mijozlari. Agar mijoz ushbu bandga rioya qilmasa\n            qoidalarga muvofiq, Kompaniya ushbu Mijoz bilan aloqani to'xtatishga haqli\n            yoki kiruvchi arizani ko'rib chiqmasdan qoldiring.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            16.2. Ma'lumotni veb-saytga mumkin bo'lgan miqdorda yuklash taqiqlanadi\n            Veb-sayt ishida uzilishlarga olib kelishi va boshqa har qanday harakatlarni amalga oshirish\n            resursning ishlashiga ta'sir qilishi mumkin bo'lgan harakatlar. Bu holda\n            bu viruslar, zararli dasturlar, ommaviy pochta jo'natmalari va degan ma'noni anglatadi\n            spam - yuqorida aytilganlarning barchasi qat'iyan man etiladi. Bundan tashqari, mijozlar\n            joylashtirilgan ma'lumotlarni o'chirish, o'zgartirish yoki tahrirlash taqiqlanadi\n            &#160; veb-saytida\n          </span>\n        </p>\n        <p>\n          <span>\n            16.3. Mijozlar veb-saytdan faqat shu maqsadda foydalanishlari mumkin\n            ko'ngilochar maqsadlarda. To'liq yoki qisman nusxa ko'chirish taqiqlanadi\n            Veb-sayt.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            16.4. Mijozlar buzg'unchilikka qaratilgan harakatlarni qilmaslik majburiyatini oladilar\n            Noqonuniy kirish huquqiga ega bo'lgan veb-sayt xavfsizlik tizimlari\n            maxfiy ma'lumotlar yoki DDoS hujumlari. Mijozlarga nisbatan,\n            ushbu qoidani buzganlikda gumon qilingan shaxslar javobgarlikka tortiladi\n            tegishli choralar: Veb-saytga kirishni to'liq taqiqlash va\n            profilni blokirovka qilish. Bundan tashqari, biz xabardor qilish huquqiga egamiz\n            Client.&#160;ning noqonuniy xatti-harakatlari bo'yicha mas'ul organlar\n          </span>\n        </p>\n        <p>\n          <span>\n            16.5. Biz har qanday yo'qotish yoki zarar uchun javobgar emasmiz\n            texnik sabablarga ko'ra mijozlarimizga yoki uchinchi shaxslarga yuklanadi\n            virus hujumlari yoki boshqa zararli dasturlardan kelib chiqqan nosozliklar\n            veb-saytga qaratilgan harakatlar.\n          </span>\n        </p>\n        <p>\n          <span>\n            16.6. Bitta Mijozning profilini o'tkazish va sotish qat'iyan man etiladi\n            boshqasiga.&#160;\n          </span>\n        </p>\n        <p>\n          <span>17. Shartnomani bekor qilish shartlari va tartibi&#160;</span>\n        </p>\n        <p>\n          <span>\n            17.1. Kompaniya Mijozning profilini (shuningdek, uning nomini) o'chirishga haqli\n            va parol) quyidagi hollarda oldindan ogohlantirmasdan:\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.1. Kompaniya xizmatlar ko'rsatishni to'xtatishga qaror qildi\n            Mijozlarning barchasi yoki ma'lum bir qismi; &#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.2. Mijozning profili qandaydir tarzda ilgari o'chirilgan bilan bog'liq\n            profil;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.3. Mijozning profili hozirda bloklangan profil bilan bog'langan\n            profil, bu holda Kompaniya profilni yopish huquqiga ega\n            aloqa turidan qat'iy nazar va hisob ma'lumotlarini to'liq blokirovka qilish\n            bu profillar. Shartnomada boshqacha qoida nazarda tutilgan bo'lmasa,\n            Mijozning profilida joylashgan mablag'lar qaytariladi\n            uni ma'lum muddat ichida, arizani to'ldirgandan so'ng darhol va\n            mijozning kompaniyaga qarzi bo'lgan summani ushlab qolish;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.4. Mijoz jinoiy fitnada qatnashadi yoki harakat qiladi\n            tizimni buzish;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.5. Mijoz dasturiy ta'minotga aralashadi\n            Veb-sayt yoki boshqa har qanday faoliyatni amalga oshirishga urinishlar;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.6. Mijoz o'z profilidan mumkin bo'lgan maqsadlarda foydalanadi\n            har qanday qonunga muvofiq noqonuniy hisoblanadi\n            maxsus yurisdiktsiya;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.1.7. Mijoz veb-saytda haqoratli yoki ma'lumotni e'lon qiladi\n            kamsituvchi xarakterga ega.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            17.2. Kompaniya mijozning profilini yopish yoki bekor qilish huquqiga ega\n            ga tegishli bildirishnoma yuborish orqali Shartnomaning amal qilish muddati\n            aloqa ma'lumotlarida ko'rsatilgan elektron pochta manzili. Bunday holatda\n            bandda ko'rsatilgan holatlar bundan mustasno, bizning harakatlarimiz\n            15 (\"Tirikish, aldash, firibgarlik va\n            jinoiy faoliyat\") va 22-moddasi (\"Shartlarni buzish\").\n            Shartnomaga ko'ra, kompaniya hisobvaraqdagi mablag'larni qaytarishga majburdir\n            Mijoz. Agar biron sababga ko'ra biz qila olmasak\n            Mijoz bilan bog'laning, pul mablag'lari vaqtincha o'tkaziladi\n            bukmeker yoki nazorat organining hisobi.\n          </span>\n        </p>\n        <p>\n          <span>18. Veb-saytga kiritilgan o'zgartirishlar</span>\n        </p>\n        <p>\n          <span>\n            18.1. Biz istalgan vaqtda, o'z ixtiyorimiz bilan,\n            Veb-saytda taqdim etilgan xizmatlarga o'zgartirishlar yoki qo'shimchalar kiritish\n            resursni saqlash va yangilash maqsadida.\n          </span>\n        </p>\n        <p>\n          <span>19. Tizim xatolari</span>\n        </p>\n        <p>\n          <span>\n            19.1. Agar o'yin davomida veb-saytda nosozlik bo'lsa,\n            Kompaniya vaziyatni imkon qadar tezroq tuzatishga harakat qiladi. Biz yo'q\n            Biz axborot vositalaridagi muammolar uchun javobgarmiz\n            uskunalarning ishlashi natijasida yuzaga keladigan texnologiyalar,\n            Mijozlar tomonidan veb-saytga kirish uchun, shuningdek, nosozliklar uchun foydalaniladi\n            Internet-provayderlarning ishi.\n          </span>\n        </p>\n        <p>\n          <span>20. Xatolar va kamchiliklar</span>\n        </p>\n        <p>\n          <span>\n            20.1. Kompaniya har qanday garovlarni cheklash yoki bekor qilish huquqiga ega.\n          </span>\n        </p>\n        <p>\n          <span>\n            20.2. Agar mijoz o'z hisobidan olingan mablag'lardan foydalangan bo'lsa\n            xato natijasida hisob, tikish qo'yish va o'yinda ishtirok etish uchun, biz\n            biz bunday garovlar va ulardan olingan yutuqlarni bekor qilishimiz mumkin\n            yordam. Agar bunday stavkalarda naqd to'lov amalga oshirilgan bo'lsa\n            mablag'lar bo'lmasa, bu summalar Mijozga o'tkazilgan deb hisoblanishi kerak\n            Ishonchli boshqaruv, Mijoz ularni birinchi navbatda qaytarishi shart\n            bizning talabimiz.\n          </span>\n        </p>\n        <p>\n          <span>\n            20.3. Kompaniya va xizmat ko'rsatuvchi provayderlar etkazilgan zarar uchun javobgar emas\n            bilan xatolar natijasida yutuq yo'qotish, shu jumladan\n            Mijoz tomondan yoki biz tomondan.\n          </span>\n        </p>\n        <p>\n          <span>\n            20.4. Kompaniya, uning distribyutorlari, filiallari, litsenziatlari, sho'ba korxonalari\n            korxonalar, shuningdek, xodimlar va menejerlar yuklamaydilar\n            tufayli yuzaga kelgan har qanday yo'qotish yoki zarar uchun javobgarlik\n            &#160;-ni ushlab turish yoki noto'g'ri ishlatish\n          </span>\n        </p>\n        <p>\n          <span>Internet orqali uzatiladigan ma'lumotlar.&#160;</span>\n        </p>\n        <p>\n          <span>21. &#160; javobgarligimizni cheklash</span>\n        </p>\n        <p>\n          <span>\n            21.1. Mijoz xizmatlardan foydalanishga mustaqil ravishda qaror qiladi\n            Veb-sayt va har qanday harakatlar va ularning oqibatlari oqibatidir\n            Mijozning shaxsiy tanlovi, uning xohishiga ko'ra, o'z xohishiga ko'ra amalga oshiriladi\n            qo'rquv va xavf.\n          </span>\n        </p>\n        <p>\n          <span>\n            21.2. Veb-saytning ishlashi paragraflarga muvofiq amalga oshiriladi\n            ushbu Shartnoma. Kompaniya qo'shimcha xizmatlarni taqdim etmaydi\n            veb-sayt va xizmatlarga nisbatan kafolatlar yoki vakolatlar\n            u bo'yicha taklif qilinadi va shu bilan uning javobgarligini istisno qiladi (in\n            qonun hujjatlarida nazarda tutilgan darajada) barcha nazarda tutilganlarga nisbatan\n            kafolatlar.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            21.3. Biz huquqbuzarliklar, beparvolik uchun javobgar emasmiz,\n            bunda oldindan aytib bo'lmaydigan yo'qotishlar va zararlar\n            moment.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            21.4. Kompaniya resurslarning mazmuni uchun javobgar emas,\n            veb-sayt orqali kirish mumkin.\n          </span>\n        </p>\n        <p>\n          <span>22. Shartlarni buzish</span>\n        </p>\n        <p>\n          <span>\n            22.1. Mijoz yo'qotishlarni to'liq qoplashga rozi\n            Kompaniya, uning sheriklari, xodimlari va manfaatlarini himoya qilish va himoya qilish\n            direktorlar har qanday da'volardan, javobgarlikdan, xarajatlardan, yo'qotishlardan va\n            tufayli kelib chiqadigan xarajatlar: &#160;\n          </span>\n        </p>\n        <p>\n          <span>22.1.1. mijoz tomonidan Shartnoma shartlarini buzish;</span>\n        </p>\n        <p>\n          <span>22.1.2. mijoz tomonidan uchinchi shaxslarning qonunlari va huquqlarini buzish;</span>\n        </p>\n        <p>\n          <span>\n            22.1.3. boshqa har qanday shaxs tomonidan veb-sayt xizmatlariga kirish huquqiga ega bo'lganda\n            mijozning identifikatsiya ma'lumotlaridan uning ruxsatisiz yoki ruxsatisiz foydalanish\n            u yoki;\n          </span>\n        </p>\n        <p>\n          <span>22.1.4. shu tarzda olingan yutuqlarni o'zlashtirish.</span>\n        </p>\n        <p>\n          <span>\n            22.2. Agar mijoz Shartnoma shartlarini buzsa, bizda\n            o'ngda:\n          </span>\n        </p>\n        <p>\n          <span>\n            22.2.1. Mijozni o'z harakatlari bilan buzayotganligi haqida xabardor qilish\n            Shartnoma shartlari va zudlik bilan bekor qilishni talab qilish\n            taqiqlangan harakatlar;\n          </span>\n        </p>\n        <p>\n          <span>22.2.2. Mijozning hisobini to'xtatib turish; &#160;</span>\n        </p>\n        <p>\n          <span>\n            22.2.3. oldindan ogohlantirmasdan mijozning hisobini bloklash;\n          </span>\n        </p>\n        <p>\n          <span>\n            22.2.4. Mijozning hisobvarag'idan to'lovlar, yutuqlar yoki summalarni undirish\n            buzilish natijasida olingan bonuslar.\n          </span>\n        </p>\n        <p>\n          <span>\n            22.3. Biz sizning foydalanuvchi nomingiz va parolingizni bekor qilishga haqlimiz\n            Shartnomaning biron bir bandiga rioya qilmagan taqdirda mijoz.\n          </span>\n        </p>\n        <p>\n          <span>23. Intellektual mulkka bo'lgan huquqlar</span>\n        </p>\n        <p>\n          <span>\n            23.1. Veb-saytdagi barcha kontent mualliflik huquqiga bog'liq va\n            Kompaniyaga tegishli bo'lgan boshqa mulkiy huquqlar. Barcha yuklab olish va\n            Veb-saytda mavjud bo'lgan bosma materiallarni yuklab olish mumkin\n            faqat bitta kompyuter uchun. Ushbu materiallarni chop etishga ruxsat beriladi\n            faqat shaxsiy va notijorat maqsadlarda foydalanish uchun.\n          </span>\n        </p>\n        <p>\n          <span>\n            23.2. Veb-saytdan foydalanish Mijozga hech qanday huquq bermaydi\n            Kompaniya yoki uchinchi shaxsga tegishli intellektual mulk\n            tomoni.\n          </span>\n        </p>\n        <p>\n          <span>\n            23.3. Savdo belgisidan har qanday foydalanish yoki qayta ishlab chiqarish taqiqlanadi.\n            brendlar, savdo belgilari, logotiplar va boshqa reklama materiallari,\n            Kompaniyaning tegishli roziligisiz veb-saytda taqdim etilgan.\n          </span>\n        </p>\n        <p>\n          <span>\n            23.4. Mijoz har qanday zarar, xarajatlar yoki xarajatlar uchun javobgar bo'ladi\n            uning taqiqlangan jinoyatni sodir etishi natijasida yuzaga kelgan xarajatlar\n            tadbirlar. Mijozlar darhol Kompaniyani xabardor qilishlari kerak\n            ular har qanday taqiqlangan faoliyatni amalga oshirishdan xabardor bo'ladilar\n            va tergovni amalga oshirishda barcha zarur yordam ko'rsatish, qaysi\n            Kompaniya taqdim etilgan ma'lumotlarni hisobga olgan holda amalga oshirishi mumkin.\n          </span>\n        </p>\n        <p>\n          <span>24. Mijozlarning shaxsiy ma'lumotlari</span>\n        </p>\n        <p>\n          <span>\n            24.1. Biz shaxsiy ma'lumotlarni himoya qilish bo'yicha talablarga rioya qilishga majburmiz\n            Kompaniya to'plangan shaxsiy ma'lumotlardan foydalanadigan shakl\n            foydalanuvchining veb-saytga tashrifi natijasida. bilan kompaniya\n            qayta ishlash majburiyatlarini o'ta jiddiylik bilan oladi\n            mijozlarimizning shaxsiy ma'lumotlari. Kompaniya qayta ishlaydi\n            Mijozlar tomonidan to'liq mos ravishda taqdim etilgan shaxsiy ma'lumotlar\n            maxfiylik siyosati.\n          </span>\n        </p>\n        <p>\n          <span>\n            24.2. Shaxsiy ma'lumotlarni taqdim etish orqali Mijozlar bunga rozilik bildiradilar\n            Kompaniya shaxsiy ma'lumotlarni qayta ishlash huquqiga ega\n            Shartnomada ko'rsatilgan maqsadlar yoki tartibga solish va\n            legal&#160;\n          </span>\n        </p>\n        <p>\n          <span>majburiyatlar.</span>\n        </p>\n        <p>\n          <span>\n            24.3. Maxfiylik siyosatiga muvofiq, biz buni qilmaslik majburiyatini olamiz\n            Mijozlarimizning shaxsiy ma'lumotlarini oshkor qilish va uzatmaslik\n            uchinchi shaxslarga, axborotni qayta ishlash tizimlari va bundan mustasno\n            agar kerak bo'lsa, undan foydalanishi mumkin bo'lgan ishchilar\n            faqat sifatli xizmatlarni taqdim etish maqsadida.\n            24.4. Biz mijozlardan olingan barcha yozishmalarning nusxalarini saqlaymiz,\n            olingan barcha ma'lumotlarni aniq qayd etish.\n          </span>\n        </p>\n        <p>\n          <span>25. Veb-saytda cookie-fayllardan foydalanish</span>\n        </p>\n        <p>\n          <span>\n            25.1. Funktsiyani ta'minlash uchun biz cookie-fayllardan foydalanamiz\n            Veb-sayt. \"Cookie\" kichik faylning maxsus matnli faylidir\n            qachon foydalanuvchining kompyuterida saqlanadigan o'lcham\n            Veb-saytga tashrif buyurib, u orqali biz aniq bilib olamiz\n            foydalanuvchilar veb-saytga yana tashrif buyurganlarida. Qo'shimcha\n            Cookie-fayllarni boshqarish va o'chirish haqida ma'lumotni veb-saytda topishingiz mumkin:\n            www.aboutcookies.org. Iltimos, fayllarimizni o'chirishni unutmang\n            Cookie-fayllar ba'zilariga kirishni bloklashi mumkin\n            veb-saytning bo'limlari va funktsiyalari.\n          </span>\n        </p>\n        <p>\n          <span>26. Shikoyatlar va bildirishnomalar</span>\n        </p>\n        <p>\n          <span>\n            26.1. Agar ish bo'yicha shikoyatlar yoki da'volar paydo bo'lsa\n            Veb-sayt, birinchi navbatda, o'zingizni yuborishingiz kerak\n            Veb-sayt orqali onlayn chat orqali qo'llab-quvvatlashni talab qiling\n            Kompaniya (kompaniyaning 24 soatlik qo'llab-quvvatlash telefon raqami 8 (800)\n            301-77-89) yoki kompaniyaning elektron pochta manziliga -\n            support@imbalance.click.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            26.2. Mijoz nizo yozuvi saqlanishiga rozi bo'ladi\n            serverda, qachon dalil sifatida foydalanish mumkin\n            da'voni ko'rib chiqish.\n          </span>\n        </p>\n        <p>\n          <span>27. Nizolarni hal qilish tartibi</span>\n        </p>\n        <p>\n          <span>\n            27.1. O'yinchi har qanday vaziyatga qarshi turishi mumkin. Kompaniya har tomonlama va\n            ta'minlangan taqdirda barcha bahsli masalalarni xolisona ko'rib chiqadi\n            aniq ma'lumotlar - faktlar va dalillar. Bahsli ma'lumotlar, bilan\n            faktlar va dalillarni qo'llash yozma ravishda taqdim etilishi kerak\n            Kompaniya veb-sayti orqali onlayn chat orqali (tel.\n            Kompaniyani kechayu kunduz qo'llab-quvvatlash - 8(800)301-77-89) yoki\n            Kompaniyaning qo'llab-quvvatlash xizmatining elektron pochta manzili - security@imbalance.click. B\n            shikoyat yoki so‘rov xati olingan kundan boshlab 14 kun ichida\n            ko'rib chiqiladi va mijozga natija haqida xabar beriladi\n            javob xatida ko'rib chiqish. Agar kerak bo'lsa\n            qo'shimcha tekshiruvlar, Kompaniya ko'rib chiqish muddatini uzaytirish huquqiga ega\n            ariza olingan kundan boshlab 30 kungacha. Maktub matnida\n            Har qanday haqoratli so'zlarni ishlatish taqiqlanadi\n            haqorat va yolg'on ma'lumotlar.&#160;\n          </span>\n        </p>\n        <p>\n          <span>28. Fors-major &#160;</span>\n        </p>\n        <p>\n          <span>\n            28.1. Kompaniya kechikishlar yoki bajarilmaganlik uchun javobgar emas\n            Shartnomada ko'rsatilgan majburiyatlar, agar ular\n            fors-major holatlari natijasida yuzaga kelgan\n            tabiiy ofatlar, urushlar, ichki tartibsizliklarni tushunishi kerak,\n            mehnat nizolari, kommunal xizmatlardagi uzilishlar,\n            DDoS hujumlari yoki Internetga olib kelishi mumkin bo'lgan boshqa hujumlar\n            Veb-sayt faoliyatiga salbiy ta'sir ko'rsatish.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            28.2. Fors-major holatlari davrida\n            veb-sayt faoliyati to'xtatilgan deb hisoblanadi, va muddati uchun\n            Ushbu davrda majburiyatlarni bajarishda kechiktirish mavjud.\n            Kompaniya qidiruv uchun barcha imkoniyatlardan foydalanish majburiyatini oladi\n            o'z majburiyatlarini to'liq bajarishga imkon beruvchi echimlar\n            shartlar oxirigacha mijozlarga\n            fors-major.&#160;\n          </span>\n        </p>\n        <p>\n          <span>29. Ogohlantirish &#160;</span>\n        </p>\n        <p>\n          <span>\n            29.1. Agar biz mijozning biron bir narsani bajarishiga ishonch hosil qila olmasak\n            majburiyatlari yoki o'zimiz hech biridan foydalana olmaymiz\n            biz haqli bo'lgan himoya vositalari, keyin u emas\n            ushbu himoya vositalaridan voz kechish sifatida talqin etiladi yoki\n            Mijozni majburiyatlarini bajarishdan ozod qiluvchi sabab sifatida.\n          </span>\n        </p>\n        <p>\n          <span>30. &#160; kelishuvining bo'linishi</span>\n        </p>\n        <p>\n          <span>\n            30.1. Agar Shartnomaning biron bir bandi o'z kuchini yo'qotsa,\n            noqonuniy yoki yuridik kuchini yo'qotgan bo'lsa, ushbu qoida\n            to'liq bo'lgan Shartnomaning qolgan qismidan uziladi\n            yuridik kuchini saqlab qoladi. Bunday hollarda, bu qism\n            haqiqiy emas deb hisoblanadi, yangilanganiga ko'ra o'zgartiriladi\n            standartlar\n          </span>\n        </p>\n        <p>\n          <span>31. Links&#160;</span>\n        </p>\n        <p>\n          <span>\n            31.1. Veb-sayt boshqa manbalarga havolalarni o'z ichiga olishi mumkin,\n            bu bizning nazoratimizdan tashqarida. Biz javobgar emasmiz\n            boshqa saytlarning mazmuni, ularning egalarining harakatlari yoki harakatsizligi uchun\n            va uchinchi tomon reklama va homiylik mazmuni uchun. Giperhavolalar\n            boshqa saytlarga faqat ma'lumot uchun taqdim etiladi.\n            maqsadlar. Mijozlar ulardan o'z tavakkalchiligida foydalanadilar.&#160;\n          </span>\n        </p>\n        <p>\n          <span>32. Bonus aksiyalari&#160;</span>\n        </p>\n        <p>\n          <span>\n            32.1. Ko'tarilgan tikish (tikish) faqat o'rnatiladi\n            naqd bonuslar va faqat bonus miqdori uchun amal qiladi. Agar\n            bonus omonat foizi, keyin tikish amal qiladi\n            foiz miqdori. Tikish hajmi o'tkazilayotgan bonus aksiyasiga bog'liq.\n            va Website.&#160; tomonidan o'rnatiladi\n          </span>\n        </p>\n        <p>\n          <span>\n            32.2. Siz naqd bonusni faqat to'liq bo'lgan taqdirda olishingiz mumkin\n            tikish.&#160;\n          </span>\n        </p>\n        <p>\n          <span>\n            Ro'yxatdan o'tish yoki boshqa hollarda pul mukofotlarini hisoblashda,\n            bonus olgandan keyin Mijozdan pul mablag'larini kiritish talab etilmaydi\n            balans, bonus yig'ish olib tashlash birinchi qadar mumkin emas\n            depozit.\n          </span>\n        </p>\n      </div>\n";
export default html;
